(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("philo-on-the-posterity-of-cain-and-his-exile-b",[{"sp": "HDR", "t": "Κεφ. I", "st": "1"}, {"sp": "N", "t": "“Ἐξῆλθε δὲ Κάιν ἀπὸ προσώπου τοῦ θεοῦ, καὶ ᾤκησεν ἐν γῇ Ναὶδ κατέναντι Ἐδέμ” (Gen. 4, 16). νυνὶ διαπορῶμεν, εἰ χρὴ τῶν ἐν ταῖς διερμηνευθείσαις βίβλοις ὑπὸ Μωυσέως τροπικώτερον ἀκούειν, τῆς ἐν τοῖς ὀνόμασι προχείρου φαντασίας πολὺ τἀληθοῦς ἀπᾳδούσης.", "st": "1"}, {"sp": "N", "t": "εἰ γὰρ πρόσωπον μὲν ἔχει τὸ ὄν, ὁ δὲ βουλόμενος αὐτὸ καταλιπεῖν ἑτέρωσε μετανίστασθαι ῥᾷστα δύναται, τί τὴν Ἐπικούρειον ἀσέβειαν ἢ τὴν τῶν Αἰγυπτίων ἀθεότητα ἢ τὰς μυθικὰς ὑποθέσεις, ὧν μεστὸς ὁ βίος ἐστί, παραιτούμεθα;", "st": "2"}, {"sp": "N", "t": "πρόσωπον μὲν γὰρ ζῴου τμῆμά ἐστιν, ὁ δὲ θεὸς ὅλον, οὐ μέρος· ὥστ’ ἀνάγκη καὶ τὰ ἄλλα προσαναπλάττειν, αὐχένα καὶ στέρνα καὶ χεῖρας ⟨καὶ⟩ βάσεις, ἔτι δ’ αὖ γαστέρα καὶ τὰ γεννητικὰ καὶ τὸ ἄλλο τῶν ἐντός τε καὶ ἐκτὸς ἀνάριθμον πλῆθος.", "st": "3"}, {"sp": "N", "t": "ἀκολουθεῖ δ’ ἐξ ἀνάγκης τῷ ἀνθρωπομόρφῳ τὸ ἀνθρωποπαθές, ἐπεὶ καὶ ταῦτα οὐ περιττὰ καὶ παρέλκοντα, τῆς δὲ τῶν ἐχόντων ἐπίκουρα ἀσθενείας ἡ φύσις ἀπειργάζετο τὰ ὅσα πρὸς τὰς οἰκείας χρείας τε καὶ ὑπηρεσίας ἀκολούθως ἐφαρμόττουσα. τὸ δὲ ὂν οὐδενὸς χρεῖον, ὥστ’ εἰ μηδὲ τῆς ἀπὸ τῶν μερῶν ὠφελείας, οὐδ’ ἂν ἔχοι μέρη τὸ παράπαν.", "st": "4"}, {"sp": "HDR", "t": "Κεφ. II", "st": "5"}, {"sp": "N", "t": "ἐξέρχεται δὲ πόθεν; ἢ ἐκ τῶν βασιλείων τοῦ πανηγεμόνος; θεοῦ δὲ οἶκος αἰσθητὸς τίς ἂν εἴη πλὴν ὅδε ὁ κόσμος, ὃν καταλείπειν ἀμήχανόν τε καὶ ἀδύνατον; πάντα γὰρ ὧν γένεσίς ἐστιν οὐρανοῦ κύκλος περισφίγξας ἐντὸς ἑαυτοῦ κατέχει. καὶ γὰρ αἱ τῶν τετελευτηκότων ἀναστοιχειούμεναι μοῖραι πάλιν εἰς τὰς τοῦ παντὸς δυνάμεις ἐξ ὧν συνέστησαν ἀποκρίνονται, τοῦ δανεισθέντος ἑκάστῳ δανείσματος κατὰ προθεσμίας ἀνίσους ἀποδιδομένου τῇ συμβαλούσῃ φύσει, ὁπότε βουληθείη τὰ ἑαυτῆς χρέα κομίζεσθαι.", "st": "5"}, {"sp": "N", "t": "καὶ μὴν ὅ γε ἐξιὼν ἀπό τινος ἐν ἑτέρῳ χωρίῳ τὸ ἀπολειπόμενον ἑαυτοῦ· τῷ δὲ συμβέβηκεν ἀκολουθεῖν τὸ χηρεύειν τινὰ μέρη τῶν ἐν κόσμῳ θεοῦ μηδὲν κενὸν μηδὲ ἔρημον ἑαυτοῦ καταλελοιπότος, ἀλλὰ πάντα διὰ πάντων ἐκπεπληρωκότος.", "st": "6"}, {"sp": "N", "t": "εἰ δὲ μήτε πρόσωπον ἔχει ὁ θεὸς ἅτε τὰς τῶν γεγονότων ἰδιότητας ἁπάντων ἐκβεβηκὼς μήτε ἐν μέρει καταγίνεται ἅτε περιέχων, οὐ περιεχόμενος, ἀδύνατον ⟨δ’⟩ ἐστὶν ὥσπερ ἐκ πόλεως τοῦδε τοῦ κόσμου μεταναστῆναί τι μέρος αὐτοῦ μηδενὸς ἀπολειφθέντος ἔξω, λοιπὸν ἂν εἴη λογισαμένους ὅτι τῶν προταθέντων οὐδὲν κυριολογεῖται τὴν δι’ ἀλληγορίας ὁδὸν φυσικοῖς ⟨φίλην⟩ ἀνδράσι τρέπεσθαι τὴν ἀρχὴν ἐνθένδε τοῦ λόγου ποιησαμένους·", "st": "7"}, {"sp": "N", "t": "εἰ τὸ ἐκ προσώπου μεταναστῆναι βασιλέως θνητοῦ χαλεπόν ἐστι, πῶς οὐ παγχάλεπον τὴν θεοῦ φαντασίαν καταλιπόντα οἴχεσθαι, μηκέτι εἰς ὄψιν ἀφικνεῖσθαι τὴν αὐτοῦ διεγνωκότα, τοῦτο δ’ ἐστὶν ἀφάνταστον αὐτοῦ γενέσθαι τὸ ψυχῆς ὄμμα πηρωθέντα;", "st": "8"}, {"sp": "N", "t": "καὶ ὅσοι μὲν ἐξ ἀνάγκης τοῦτο ὑπέμειναν ἀπαραιτήτου δυνάμεως κράτει πιεσθέντες, ἐλέου μᾶλλον ἢ μίσους τυγχάνοιεν ἄν· ὅσοι δὲ ἑκουσίῳ γνώμῃ τὸ ὂν ἐξετράποντο, ὑπερβάλλοντες καὶ τὸν αὐτῆς ὅρον κακίας – τί γὰρ ἂν ἰσοστάσιον εὑρεθείη κακόν; – μὴ τὰς ἐξ ἔθους, ἀλλὰ καινὰς καὶ παρηλλαγμένας διδότωσαν δίκας. ἦ καινοτέραν καὶ μείζονα ἐπινοῶν οὐκ ἄν τις εὕροι τῆς ἀπὸ τοῦ πανηγεμόνος ἐξόδου καὶ φυγῆς.", "st": "9"}, {"sp": "HDR", "t": "Κεφ. III", "st": "10"}, {"sp": "N", "t": "τὸν μὲν οὖν Ἀδὰμ ὁ θεὸς ἐκβάλλει, ὁ δὲ Κάιν ἐθελοντὴς ἐξέρχεται, δηλοῦντος ἡμῖν Μωυσέως ἑκατέρου τρόπου εἶδος, ἑκούσιόν τε καὶ ἀκούσιον. ἀλλὰ τὸ μὲν ἀκούσιον ἅτε οὐχ ἡμετέρᾳ γνώμῃ συνιστάμενον λήψεται τὴν ἐνδεχομένην αὖθις ἴασιν· “ἐξαναστήσει γὰρ ὁ θεὸς σπέρμα ἕτερον ἀντ’ Ἄβελ, ὃν ἀπέκτεινε Κάιν” (Gen. 4, 25) ψυχῇ τῇ μὴ παρ’ ἑαυτῆς τραπείσῃ, γέννημα ἄρρεν, Σὴθ τὸν ποτισμόν.", "st": "10"}, {"sp": "N", "t": "τὸ δὲ ἑκούσιον ἅτε βουλῇ καὶ προμηθείᾳ γενόμενον ἀνιάτους εἰς ἀεὶ κῆρας ἐνδέξεται. καθάπερ γὰρ τὰ ἐκ προνοίας ἀμείνω τῶν ἀκουσίων κατορθώματα, τὸν αὐτὸν τρόπον ἐν τοῖς ἁμαρτήμασι κουφότερα τῶν ἑκουσίων τὰ ἀκούσια.", "st": "11"}, {"sp": "HDR", "t": "Κεφ. IV", "st": "12"}, {"sp": "N", "t": "τὸν μὲν οὖν Κάιν ἐκ προσώπου τοῦ θεοῦ μεταστάντα ἡ τιμωρὸς ἀσεβῶν ἐκδέξεται δίκη. Μωυσῆς δὲ τοῖς γνωρίμοις αὑτοῦ παράγγελμα κάλλιστον ὑποθήσεται, “ἀγαπᾶν τὸν θεὸν καὶ εἰσακούειν καὶ ἔχεσθαι αὐτοῦ” (Deut. 30, 20)· ταύτην γὰρ εἶναι ζωὴν τὴν πρὸς ἀλήθειαν εὐήμερόν τε καὶ μακραίωνα. πάνυ δ’ ἐμφαντικῶς ἐπὶ τὴν τοῦ τριποθήτου καὶ ἀξιεράστου καλεῖ τιμὴν εἰπὼν ἔχεσθαι αὐτοῦ, τὸ συνεχὲς καὶ ἐπάλληλον καὶ ἀδιάστατον τῆς κατ’ οἰκείωσιν ἁρμονίας καὶ ἑνώσεως παριστάς.", "st": "12"}, {"sp": "N", "t": "ἃ μὲν δὴ τοῖς ἄλλοις παραινεῖ, ταῦτά ἐστι καὶ τοιαῦτα. αὐτὸς δ’ οὕτως ἀπαύστως ὀρέγεται τοῦ ὁρᾶν καὶ πρὸς αὐτοῦ ὁρᾶσθαι, ὥσθ’ ἱκετεύει δυστόπαστον οὖσαν τὴν ἑαυτοῦ φύσιν δηλῶσαι γνωρίμως (Exod. 33, 13), ἵν’ ἤδη ποτὲ ἀψευδοῦς δόξης μεταλαβὼν ἀβεβαίου ἐνδοιασμοῦ βεβαιοτάτην πίστιν ἀλλάξηται. καὶ ἐπιτείνων οὐκ ἀνήσει τὸν πόθον, ἀλλὰ καὶ γνοὺς ὅτι δυσθηράτου μᾶλλον δὲ ἀνεφίκτου πράγματος ἐρᾷ, ὅμως ἐπαγωνιεῖται μηδὲν συντόνου σπουδῆς ἀνιείς, ἀλλὰ πᾶσι τοῖς παρ’ ἑαυτοῦ εἰς τὸ τυχεῖν ἀπροφασίστως καὶ ἀόκνως συγχρώμενος.", "st": "13"}, {"sp": "HDR", "t": "Κεφ. V", "st": "14"}, {"sp": "N", "t": "ἤδη γοῦν καὶ εἰς τὸν γνόφον ὅπου ἦν ὁ θεὸς εἰσελεύσεται (Exod. 20, 21), τουτέστιν εἰς τὰς ἀδύτους καὶ ἀειδεῖς περὶ τοῦ ὄντος ἐννοίας. οὐ γὰρ ἐν γνόφῳ τὸ αἴτιον οὐδὲ συνόλως ἐν τόπῳ, ἀλλ’ ὑπεράνω καὶ τόπου καὶ χρόνου· τὰ γὰρ γεγονότα πάντα ὑποζεύξας ἑαυτῷ περιέχεται μὲν ὑπ’ οὐδενός, ἐπιβέβηκε δὲ πᾶσιν. ἐπιβεβηκὼς δὲ καὶ ἔξω τοῦ δημιουργηθέντος ὢν οὐδὲν ἧττον πεπλήρωκε τὸν κόσμον ἑαυτοῦ· διὰ γὰρ * * * δυνάμεως ἄχρι περάτων τείνας ἕκαστον ἑκάστῳ κατὰ τοὺς ἁρμονίας λόγους συνύφηνεν.", "st": "14"}, {"sp": "N", "t": "ὅταν οὖν φιλόθεος ψυχὴ τὸ τί ἐστι τὸ ὂν κατὰ τὴν οὐσίαν ζητῇ, εἰς ἀειδῆ καὶ ἀόρατον ἔρχεται ζήτησιν, ἐξ ἧς αὐτῇ περιγίνεται μέγιστον ἀγαθόν, καταλαβεῖν ὅτι ἀκατάληπτος ὁ κατὰ τὸ εἶναι θεὸς παντὶ καὶ αὐτὸ τοῦτο ἰδεῖν ὅτι ἐστὶν ἀόρατος.", "st": "15"}, {"sp": "N", "t": "δοκεῖ δέ μοι καὶ πρὶν ἄρξασθαι τῆσδε τῆς σκέψεως ὁ ἱεροφάντης τὸ μέγιστον αὐτῆς κατανοῆσαι, ἐξ ὧν αὐτὸν ἱκετεύει τὸν ὄντα μηνυτὴν καὶ ὑφηγητὴν τῆς ἑαυτοῦ φύσεως γενέσθαι. λέγει γάρ· “ἐμφάνισόν μοι σεαυτόν” (Exod. 33, 13), ἐναργέστατα διὰ τούτου παριστὰς ὅτι τῶν γεγονότων ἱκανὸς οὐδὲ εἷς ἐξ ἑαυτοῦ τὸν κατὰ τὸ εἶναι θεὸν ἀναδιδαχθῆναι.", "st": "16"}, {"sp": "HDR", "t": "Κεφ. VI", "st": "17"}, {"sp": "N", "t": "διὰ τοῦτο καὶ Ἀβραὰμ ἐλθὼν εἰς τὸν τόπον, ὃν εἶπεν αὐτῷ ὁ θεός, τῇ τρίτῃ ἡμέρᾳ ἀναβλέψας ὁρᾷ τὸν τόπον μακρόθεν (Gen. 22, 3. 4). ποῖον τόπον; ἆρ’ εἰς ὃν ἦλθε; καὶ πῶς ἔστι μακράν, εἴπερ ἔφθη παραγενόμενος;", "st": "17"}, {"sp": "N", "t": "ἀλλὰ μήποτε ὅπερ αἰνίττεται τοιοῦτόν ἐστιν· ὁ σοφὸς αἰεὶ γλιχόμενος κατανοῆσαι τὸν ἡγεμόνα τοῦ παντός, ὅταν τὴν δι’ ἐπιστήμης καὶ σοφίας ἀτραπὸν βαδίζῃ, λόγοις μὲν προεντυγχάνει θείοις παρ’ οἷς προκαταλύει, τρέπεσθαι δὲ τὴν ἄλλην ἐγνωκὼς ἐπέχεται· διοιχθέντων γὰρ τῶν διανοίας ὀμμάτων ὀξυδερκέστερον εἶδεν ὅτι ἐπὶ τὴν δυσαλώτου πράγματος θήραν ἀναδέδυκεν ἐξαναχωροῦντος αἰεὶ καὶ μακρὰν ἀφισταμένου καὶ φθάνοντος ἀπείρῳ τῷ μεταξὺ διαστήματι τοὺς διώκοντας.", "st": "18"}, {"sp": "N", "t": "εὖ γοῦν νομίζει, ὅτι πάνθ’ ὅσα τῶν ὑπ’ οὐρανὸν ὠκυδρομώτατα ἑστάναι ἂν δόξαι πρὸς τὴν ἡλίου καὶ σελήνης καὶ τῶν ἄλλων φορὰν ἀστέρων ἀντεξετασθέντα. καίτοι σύμπας οὐρανὸς ὑπὸ θεοῦ γέγονεν, αἰεὶ δὲ τὸ ποιοῦν τοῦ γινομένου προελήλυθεν· ὥστε ἐξ ἀνάγκης οὐ μόνον τὰ ἄλλα τῶν παρ’ ἡμῖν, ἀλλὰ καὶ τὸ πάντων ὀξυκινητότατον, ὁ νοῦς, ἀπεριγράφοις ⟨ἂν⟩ ἀπολειφθείη τῆς καταλήψεως τοῦ αἰτίου διαστήμασιν. ἀλλ’ οἱ μὲν ἀστέρες παραμείβονται τὰ κινούμενα καὶ αὐτοὶ κινούμενοι, ὁ δὲ θεός, τὸ παραδοξότατον, ἑστὼς ἔφθακε πάντα.", "st": "19"}, {"sp": "N", "t": "λέγεται δ’ ὅτι καὶ ἐγγύτατα ὁ αὐτὸς ὢν καὶ μακράν ἐστιν, ἁπτόμενος μὲν ταῖς ποιητικαῖς καὶ κολαστηρίοις δυνάμεσι πλησίον ὑπαρχούσαις ἑκάστου, πορρωτάτω δὲ τῆς κατὰ τὸ εἶναι φύσεως αὑτοῦ τὸ γενητὸν ἀπεληλακώς, ὡς μηδὲ κατὰ τὰς ἀκραιφνεῖς καὶ ἀσωμάτους τῆς διανοίας ἐπιβολὰς ψαῦσαι δύνασθαι.", "st": "20"}, {"sp": "N", "t": "τοῖς μὲν οὖν φιλοθέοις τὸ ὂν ἀναζητοῦσι, κἂν μηδέποτε εὕρωσι, συγχαίρομεν – ἱκανὴ γὰρ ἐξ ἑαυτῆς προευφραίνειν ἐστὶν ἡ τοῦ καλοῦ ζήτησις, κἂν ἀτυχῆται τὸ τέλος – , τῷ δὲ φιλαύτῳ Κάιν συναχθόμεθα, ὃς ἀφάνταστον τὴν ἑαυτοῦ ψυχὴν τοῦ ὄντος καταλέλοιπεν, τὸ ᾧ μόνῳ βλέπειν ἠδύνατο ἑκουσίως πηρώσας.", "st": "21"}, {"sp": "HDR", "t": "Κεφ. VII", "st": "22"}, {"sp": "N", "t": "Ἄξιον δὲ σκέψασθαι καὶ τὴν χώραν, εἰς ἣν ἐκ προσώπου γενόμενος θεοῦ στέλλεται· ἔστι δὲ ἣ καλεῖται σάλος, δηλοῦντος τοῦ νομοθέτου ὅτι ὁ ἄφρων ἀστάτοις καὶ ἀνιδρύτοις ὁρμαῖς κεχρημένος σάλον καὶ κλόνον, οἷα κυμαῖνον πέλαγος πρὸς ἐναντίων πνευμάτων χειμῶνος ὥρᾳ, ὑπομένει, γαλήνης δὲ ἢ νηνεμίας ἀλλ’ οὐδ’ ὄναρ ἐπῄσθηται. ὥσπερ δ’ ὅταν ναῦς σαλεύῃ θαλαττεύουσα, τότ’ οὔτε πλεῖν οὔτε ὁρμεῖν ἐστιν ἱκανή, διαφερομένη δὲ ὧδε κἀκεῖσε πρὸς ἑκάτερον τοῖχον ἀποκλίνει καὶ ταλαντεύουσα ἀντιρρέπει, οὕτως ὁ φαῦλος παραφόρῳ καὶ χειμαινούσῃ διανοίᾳ κεχρημένος εὐθύνειν τὸν ἑαυτοῦ πλοῦν ἀπταίστως ἀδυνατῶν αἰεὶ σαλεύει βίου μελετῶν ἀνατροπήν.", "st": "22"}, {"sp": "N", "t": "ὁ δ’ εἱρμὸς τῆς ἀκολουθίας οὐ μετρίως με καταπλήττει· συμβαίνει γὰρ τὸ [μὲν] τῷ ἑστῶτι πλησιάζον ἠρεμίας διὰ πόθον ὁμοιότητος ἐφίεσθαι. τὸ μὲν οὖν ἀκλινῶς ἑστὼς ὁ θεός ἐστι, τὸ δὲ κινητὸν ἡ γένεσις· ὥστε ὁ μὲν προσιὼν θεῷ στάσεως ἐφίεται, ὁ δὲ ἀπαλλαττόμενος ἅτε γενέσει τῇ τρεπομένῃ προσιὼν κατὰ τὸ εἰκὸς φορεῖται.", "st": "23"}, {"sp": "HDR", "t": "Κεφ. VIII", "st": "24"}, {"sp": "N", "t": "διὰ τοῦτο ἐν ταῖς ἀραῖς γέγραπται ὅτι “οὐκ ἀναπαύσει σε, οὐδ’ οὐ μὴ γένηται στάσις τῷ ἴχνει τοῦ ποδός σου” καὶ μικρὸν ὕστερον ὅτι “ἔσται ἡ ζωή σου κρεμαμένη ἀπέναντι τῶν ὀφθαλμῶν σου” (Deut. 28, 65. 66). πέφυκε γὰρ ὁ ἄφρων αἰεὶ παρὰ τὸν ὀρθὸν λόγον κινούμενος ἠρεμίᾳ καὶ ἀναπαύσει δυσμενὴς εἶναι καὶ ἐπὶ μηδενὸς ἑστάναι παγίως καὶ ἐρηρεῖσθαι δόγματος.", "st": "24"}, {"sp": "N", "t": "ἄλλοτε γοῦν ἀλλοῖα δοξάζει καὶ περὶ τῶν αὐτῶν ἔστιν ὅτε μηδενὸς περὶ αὐτὰ συμβεβηκότος καινοτέρου τἀναντία, μέγας καὶ μικρὸς καὶ ἐχθρὸς καὶ φίλος καὶ πάνθ’, ὡς ἔπος εἰπεῖν, τὰ μαχόμενα ἐν ἀκαρεῖ χρόνου γινόμενος. καὶ ἔστιν αὐτῷ, ὅπερ ἔφη ὁ νομοθέτης, πᾶσα ἡ ζωὴ κρεμαμένη, βάσιν οὐκ ἔχουσα ἀκράδαντον, ἀλλὰ πρὸς τῶν ἀντισπώντων καὶ ἀντιμεθελκόντων ἀεὶ φορουμένη πραγμάτων.", "st": "25"}, {"sp": "N", "t": "οὗ χάριν ἐν ἑτέροις “κεκατηραμένον ὑπὸ θεοῦ τὸν κρεμάμενον ἐπὶ ξύλου” φησίν (Deut. 21, 23), ὅτι, θεοῦ δέον ἐκκρέμασθαι, ὁ δὲ ἀπῃώρησεν ἑαυτὸν σώματος, ὅς ἐστιν ἐν ἡμῖν ξύλινος ὄγκος, ἐπιθυμίαν ἐλπίδος ἀντικαταλλαξάμενος, ἀγαθοῦ τελείου μέγιστον κακόν. ἐλπὶς μὲν γὰρ τῶν ἀγαθῶν οὖσα προσδοκία ἐκ τοῦ φιλοδώρου θεοῦ τὴν διάνοιαν ἀρτᾷ, ἐπιθυμία δὲ ἀλόγους ἐμποιοῦσα ὀρέξεις ἐκ τοῦ σώματος, ὃ δεξαμενὴν καὶ χώραν ἡδονῶν ἡ φύσις ἐδημιούργησεν.", "st": "26"}, {"sp": "HDR", "t": "Κεφ. IX", "st": "27"}, {"sp": "N", "t": "οὗτοι μὲν οὖν ὥσπερ ἀπ’ ἀγχόνης τῆς ἐπιθυμίας ἐκκρεμάσθωσαν. Ἀβραὰμ δὲ ὁ σοφὸς ἐπειδὴ ἕστηκε, συνεγγίζει τῷ ἑστῶτι θεῷ· λέγει γὰρ ὅτι “ἑστὼς ἦν ἔναντι κυρίου καὶ ἐγγίσας εἶπεν” (Gen. 18, 22. 23). ὄντως γὰρ ἀτρέπτῳ ψυχῇ πρὸς τὸν ἄτρεπτον θεὸν μόνῃ πρόσοδός ἐστι, καὶ ἡ τοῦτον διακειμένη τὸν τρόπον ἐγγὺς ὡς ἀληθῶς ἵσταται δυνάμεως θείας.", "st": "27"}, {"sp": "N", "t": "τό γε μὴν χρησθὲν τῷ πανσόφῳ Μωυσῇ λόγιον ἐναργέστατα δηλοῖ τὴν περὶ τὸν σπουδαῖον βεβαιοτάτην εὐστάθειαν, ἔστι δὲ τὸ λόγιον τοιόνδε· “σὺ δὲ αὐτοῦ στῆθι μετ’ ἐμοῦ” (Deut. 5, 31)· ἐξ οὗ δύο παρίσταται, ἓν μὲν ὅτι τὸ ὂν τὸ τὰ ἄλλα κινοῦν καὶ τρέπον ἀκίνητόν τε καὶ ἄτρεπτον, ἕτερον δ’ ὅτι τῆς ἑαυτοῦ φύσεως, ἠρεμίας, τῷ σπουδαίῳ μεταδίδωσιν. ὡς γὰρ οἶμαι κανόνι ὀρθῷ τὰ στρεβλὰ εὐθύνεται, οὕτως τὰ κινούμενα κράτει τοῦ ἑστῶτος ἐπέχεταί τε καὶ ἵσταται.", "st": "28"}, {"sp": "N", "t": "νυνὶ μὲν οὖν ἑτέρῳ στῆναι μετ’ αὐτοῦ παραγγέλλει. ἀλλαχόθι δέ φησιν· “ἐγὼ καταβήσομαι μετὰ σοῦ εἰς Αἴγυπτον, καὶ ἀναβιβάσω σε εἰς τέλος” (Gen. 46, 4), οὐχὶ σὺ μετ’ ἐμοῦ. διὰ τί; ὅτι θεοῦ μὲν ἴδιον ἠρεμία καὶ στάσις, γενέσεως δὲ μετάβασίς τε καὶ μεταβατικὴ πᾶσα κίνησις.", "st": "29"}, {"sp": "N", "t": "ὅταν μὲν οὖν πρὸς τὸ ἴδιον ἀγαθὸν καλῇ, “σὺ μετ’ ἐμοῦ στῆθι” φησίν, οὐκ “ἐγὼ μετὰ σοῦ”· οὐ γὰρ στήσεται ὁ θεός, ἀλλ’ ἀεὶ ἕστηκεν. ὅταν δὲ πρὸς τὸ οἰκεῖον γενέσεως ἔρχηται, ὀρθότατα ἐρεῖ· “ἐγὼ μετὰ σοῦ καταβήσομαι”· σοὶ γὰρ ἡ τόπων ἐνάλλαξις ἁρμόζει· ὥστε μετ’ ἐμοῦ μὲν οὐδεὶς κάτεισιν – ἐγὼ γὰρ οὐ τρεπόμενος – , στήσεται δ’ ὅτιπερ ἠρεμία μοι φίλον· σὺν δὲ τοῖς κατιοῦσι μεταβατικῶς – ἀδελφὸν γὰρ καὶ συγγενὲς αὐτοῖς μετάβασις – ἐγὼ καταβήσομαι τοπικῶς οὐ χωρία ἐναλλάττων, ὃς τὸ πᾶν ἐμαυτοῦ πεπλήρωκα.", "st": "30"}, {"sp": "N", "t": "καὶ τοῦτο μέντοι ποιῶ διὰ φύσεως οἶκτον λογικῆς, ἵνα ἐκ τοῦ τῶν παθῶν ᾅδου πρὸς τὸν ὀλύμπιον χῶρον ἀρετῆς ἀναβιβασθῇ ποδηγετοῦντος ἐμοῦ, ὃς τὴν εἰς οὐρανὸν ἄγουσαν ὁδὸν ἀνατεμὼν λεωφόρον ἱκέτισι ψυχαῖς, ὡς μὴ κάμνοιεν βαδίζουσαι, πάσαις ἀποδέδειχα.", "st": "31"}, {"sp": "HDR", "t": "Κεφ. X", "st": "32"}, {"sp": "N", "t": "Δεδηλωκότες οὖν ἑκάτερον, ἠρεμίαν τε ἀστείου καὶ ἄφρονος σάλον, τὸ ἑπόμενον τῷ λόγῳ συνεπισκεψώμεθα. φησὶ γὰρ Ναίδ, τὸν κλόνον, εἰς ὃν ἡ ψυχὴ μετῳκίσατο, ἀπέναντι Ἐδέμ. συμβολικῶς δέ ἐστιν Ἐδὲμ ὀρθὸς καὶ θεῖος λόγος, παρὸ καὶ ἑρμηνείαν ἔχει “τρυφήν”, ὅτι ἐνευφραίνεται καὶ ἐντρυφᾷ πρὸ τῶν ἄλλων ἀμιγέσι καὶ ἀκράτοις, ἔτι δὲ ἀρτίοις καὶ πλήρεσι κεχρημένος ἀγαθοῖς ὕοντος τοῦ πλουτοδότου θεοῦ τὰς παρθένους καὶ ἀθανάτους χάριτας αὑτοῦ. φύσει δὲ μάχεται ἀγαθῷ κακόν, ἄδικον δικαίῳ, φρόνιμον ἄφρονι καὶ πάνθ’ ὅσα ἀρετῆς πρὸς τὰ κακίας εἴδη. τοιοῦτόν ἐστι τὸ Ναὶδ ἀντικρὺς [καὶ] εἶναι Ἐδέμ.", "st": "32"}, {"sp": "HDR", "t": "Κεφ. XI", "st": "33"}, {"sp": "N", "t": "Ταῦτ’ εἰπών φησιν ἑξῆς· “καὶ ἔγνω Κάιν [φησί] τὴν γυναῖκα αὐτοῦ, καὶ συλλαβοῦσα ἔτεκεν τὸν Ἐνώχ· καὶ ἦν οἰκοδομῶν πόλιν, καὶ ἐπωνόμασε τὴν πόλιν ἐπὶ τῷ ὀνόματι τοῦ υἱοῦ αὐτοῦ Ἐνώχ” (Gen. 4, 17). ἆρ’ οὐκ εἰκὸς διαπορῆσαι, τίνα ἔγνω γυναῖκα ὁ Κάιν; γένεσις γὰρ οὐδεμιᾶς ἄλλης μετὰ τὴν ἐκ τῆς πλευρᾶς διαπλασθεῖσαν Εὔαν ἄχρι νῦν μεμήνυται γυναικός.", "st": "33"}, {"sp": "N", "t": "εἰ δὲ φήσει τις ἀδελφῇ τὸν Κάιν συνεληλυθέναι, χωρὶς τοῦ ἀνοσίου καὶ ψεύσεται· τὰς γὰρ θυγατέρας Ἀδὰμ ὀψὲ γεγενημένας εἰσάγει. τί οὖν χρὴ λέγειν; γυναῖκα ἀσεβοῦς λογισμοῦ, ὥς γε οἴομαι, καλεῖ δόξαν, ἣν περὶ τῶν πραγμάτων τίθεται καθάπερ μυρίοι τῶν φιλοσοφησάντων, οἱ μὲν τὰ αὐτά, οἱ δὲ καὶ διαφέροντα εἰσηγησάμενοι τῷ βίῳ δόγματα.", "st": "34"}, {"sp": "N", "t": "τίς οὖν ἐστιν ἀσεβοῦς δόξα; μέτρον εἶναι πάντων χρημάτων τὸν ἀνθρώπινον νοῦν· ᾗ καὶ τῶν παλαιῶν τινα σοφιστῶν ὄνομα Πρωταγόραν φασὶ χρήσασθαι, τῆς Κάιν ἀπονοίας ἔκγονον. τεκμαίρομαι δὲ ἐνθένδε ὅτι γνωρισθεῖσα αὐτῷ ἡ γυνὴ τὸν Ἐνὼχ ἀπέτεκεν· ἑρμηνεύεται δὲ Ἐνὼχ χάρις σου.", "st": "35"}, {"sp": "N", "t": "εἰ γὰρ πάντων μέτρον ἐστὶν ἄνθρωπος, χάρις ἐστὶ καὶ δωρεὰ τοῦ νοῦ τὰ πάντα, ὥστε ὀφθαλμῷ μὲν κεχάρισται τὸ βλέπειν, ὠσὶ δὲ τὸ ἀκούειν, ἑκάστῃ δὲ τῶν ἄλλων αἰσθήσεων τὸ αἰσθάνεσθαι, καὶ τῷ κατὰ τὴν προφορὰν μέντοι λόγῳ τὸ λέγειν· εἰ δὲ καὶ ταῦτα, καὶ αὐτὸ δήπου ⟨τὸ⟩ νοεῖν, ἐν ᾧ μυρία ἐννοήματα, διανοήσεις, βουλαί, προμήθειαι, καταλήψεις, ἐπιστῆμαι, τέχναι, διαθέσεις, ἄλλων ἀριθμὸς δυνάμεων ἀδιεξίτητος.", "st": "36"}, {"sp": "N", "t": "τί οὖν ἔτι σεμνομυθούμενοι περὶ ὁσιότητος καὶ θεοῦ τιμῆς λέγειν τε καὶ ἀκούειν ἐγνώκατε, εἴ γε ἔχετε παρ’ ἑαυτοῖς τὸν ἀντίθεον νοῦν, ὃς πάντα ἀνὰ κράτος τὰ κατ’ ἀνθρώπους ἀναψάμενος ἀγαθά τε καὶ κακὰ τοῖς μὲν ἀμφότερα κερασάμενος, τοῖς δὲ θάτερα ἄκρατα ἐπιπέμπει;", "st": "37"}, {"sp": "N", "t": "κἂν ἄρα τις γραφὴν ἀσεβείας ἐπενέγκῃ καθ’ ὑμῶν, ἀπολογούμενοι θαρρεῖτε φάσκοντες παρ’ ὑφηγητῇ καὶ διδασκάλῳ πάνυ καλῷ πεπαιδεῦσθαι Κάιν, ὃς τὸ πλησίον πρὸ τοῦ μακρὰν αἰτίου παρῄνει τιμᾶν· ᾧ διά τε ἄλλα προσεκτέον καὶ μάλισθ’ ὅτι σαφέσιν ἔργοις τὴν τοῦ δόγματος ἰσχὺν ἐπεδείξατο νικήσας τὸν τῆς ἐναντίας δόξης εἰσηγητὴν Ἄβελ καὶ ἅμ’ αὐτῷ καὶ τὴν δόξαν ἐκποδὼν ἀνελών.", "st": "38"}, {"sp": "N", "t": "ἀλλὰ παρ’ ἔμοιγε καὶ φίλοις τοῖς ἐμοῖς τῆς μετὰ ἀσεβῶν ζωῆς ὁ μετὰ εὐσεβῶν αἱρετώτερος ἂν εἴη θάνατος· τοὺς μὲν γὰρ οὕτως ἀποθανόντας ἡ ἀθάνατος ἐκδέξεται ζωή, τοὺς δὲ ἐκείνως ζῶντας ὁ ἀίδιος θάνατος.", "st": "39"}, {"sp": "HDR", "t": "Κεφ. XII", "st": "40"}, {"sp": "N", "t": "ἐπεὶ δὲ ὁ Κάιν τὸν Ἐνὼχ γεγέννηκε καὶ αὖθις ἔκγονος τοῦ Σὴθ πάλιν Ἐνὼχ ὀνομάζεται (Gen. 4, 17. 5, 18), σκεπτέον ἂν εἴη πότερον ἑτέρους ἢ τοὺς αὐτοὺς εἶναι συμβέβηκεν. ἐρευνήσωμεν δ’ ἅμα τούτοις καὶ ⟨τὰς⟩ τῶν ἄλλων ὁμωνύμων διαφοράς. ὥσπερ γὰρ Ἐνώχ, οὕτω καὶ Μαθουσάλα καὶ Λάμεχ ἀπόγονοι μὲν Κάιν, ἀπόγονοι δ’ οὐδὲν ἧττον καὶ τοῦ Σήθ εἰσι (Gen. 4, 18. 5, 21. 25).", "st": "40"}, {"sp": "N", "t": "χρὴ τοίνυν εἰδέναι ὅτι τῶν λεχθέντων ἕκαστον ὀνομάτων ἑρμηνευθὲν διπλοῦν ἐστιν. ἑρμηνεύεται δ’ ὁ μὲν Ἐνώχ, καθάπερ εἶπον, χάρις σου, Μαθουσάλα δ’ ἐξαποστολὴ θανάτου, ὁ δ’ αὖ Λάμεχ ταπείνωσις. τὸ μὲν οὖν “χάρις σου” λέγεται μὲν πρὸς τὸν ἐν ἡμῖν νοῦν ὑπ’ ἐνίων, λέγεται δὲ καὶ πρὸς τὸν τῶν ὅλων ὑπὸ τῶν ἀμεινόνων.", "st": "41"}, {"sp": "N", "t": "οἱ μὲν οὖν φάσκοντες δωρεὰν εἶναι τῆς ἑαυτῶν ψυχῆς πάνθ’ ὅσα ἐν τῷ νοεῖν ἢ αἰσθάνεσθαι ἢ λέγειν, ἀσεβῆ καὶ ἄθεον εἰσηγούμενοι δόξαν γένει τῷ Κάιν προσκεκληρώσθωσαν, ὃς μηδ’ αὑτοῦ κρατεῖν ἱκανὸς ὢν καὶ τῶν ἄλλων ἁπάντων ἀπετόλμησεν [ὡς] εἰπεῖν ὡς ἔχοι τὴν παντελῆ κτῆσιν· οἱ δ’ ὅσα ἐν γενέσει καλὰ μὴ σφετεριζόμενοι, χάρισι δὲ ταῖς θείαις ἐπιγράφοντες, εὐγενεῖς πρὸς ἀλήθειαν οὐκ ἐκ παλαιπλουσίων ἀλλ’ ἐκ φιλαρέτων φύντες, ὑπὸ ἀρχηγέτῃ τῷ Σὴθ τετάχθωσαν.", "st": "42"}, {"sp": "N", "t": "δυσεύρετον σφόδρα τὸ τούτων ἐστὶ γένος ἀποδιδρασκόντων τὸν ἐπίβουλον καὶ ῥᾳδιουργὸν καὶ πανοῦργον καὶ κεχυμένον παθῶν τε καὶ κακιῶν πλήρη βίον. οὓς γὰρ ὁ θεὸς εὐαρεστήσαντας αὐτῷ μετεβίβασε καὶ μετέθηκεν ἐκ φθαρτῶν εἰς ἀθάνατα γένη, παρὰ τοῖς πολλοῖς οὐκέθ’ εὑρίσκονται.", "st": "43"}, {"sp": "HDR", "t": "Κεφ. XIII", "st": "44"}, {"sp": "N", "t": "διεσταλκότες οὖν τὰ περὶ τὸν Ἐνὼχ σημαινόμενα μέτιμεν ἑξῆς ἐπὶ τὸν Μαθουσάλα, ὃς ἦν ἐξαποστολὴ θανάτου. δύο δ’ ἐκ ταύτης παρίσταται τῆς φωνῆς, ἓν μὲν καθ’ ὅ τινι ἐπιπέμπεται θάνατος, ἕτερον δὲ καθ’ ὃ ἀπό τινος ἀποστέλλεται. ὅτῳ μὲν οὖν ἐπιπέμπεται, θνῄσκει πάντως ἐκεῖνος, ἀφ’ οὗ δὲ ἀποστέλλεται, ζῇ τε καὶ περίεστι.", "st": "44"}, {"sp": "N", "t": "τῷ μὲν δὴ Κάιν ὁ τὸν θάνατον δεχόμενός ἐστιν οἰκεῖος ἀεὶ τὸν πρὸς ἀρετὴν βίον θνῄσκοντι, τῷ δὲ Σὴθ συγγενέστατος ἀφ’ οὗπερ ἀποστέλλεται καὶ διατειχίζεται τὸ ἀποθνῄσκειν· τὴν γὰρ ἀληθῆ ζωὴν ὁ σπουδαῖος κεκάρπωται.", "st": "45"}, {"sp": "N", "t": "καὶ μὴν ὅ γε Λάμεχ ταπείνωσις ὢν ἀμφίβολός ἐστιν· ἢ γὰρ ὑφιεμένων τῶν τῆς ψυχῆς τόνων κατὰ τὰ ἐξ ἀλόγων παθῶν ἐγγενόμενα νοσήματά τε καὶ ἀρρωστήματα ταπεινούμεθα ἢ κατ’ ἀρετῆς ζῆλον στέλλοντες ἑαυτοὺς ἀπὸ οἰδούσης οἰήσεως.", "st": "46"}, {"sp": "N", "t": "ἡ μὲν οὖν προτέρα γίνεται κατ’ ἀσθένειαν, εἶδος τῆς πολυμόρφου καὶ πολυτρόπου λέπρας οὖσα· ὅταν γὰρ ἡ ὄψις ταπεινοτέρα φαίνηται τὴν ὁμαλὴν καὶ εὔτονον κλασθεῖσα φαντασίαν, τὴν χαλεπὴν νόσον λέπραν ὁ νομοθέτης φησὶ γενέσθαι (Lev. 13, 3).", "st": "47"}, {"sp": "N", "t": "ἡ δὲ ἑτέρα ἀπὸ ἰσχύος συνίσταται καρτερᾶς, ᾗ καὶ ἱλασμὸς ἕπεται κατὰ τὸν τῆς δεκάδος ἀριθμὸν τέλειον· προστέτακται γὰρ τὰς ψυχὰς ταπεινοῦν δεκάτῃ τοῦ μηνός (Lev. 23, 27), ὅπερ ἐστὶ μεγαλαυχίαν ἀποτίθεσθαι, ἧς ἡ ἀπόθεσις ἀδικημάτων ἑκουσίων καὶ ἀκουσίων ἐργάζεται παραίτησιν. ὁ μὲν οὖν οὕτως ταπεινὸς Λάμεχ ἔκγονος μέν ἐστι Σήθ, πατὴρ δὲ τοῦ δικαίου Νῶε, ὁ δὲ ἐκείνως ἐκβλάστημα Κάιν.", "st": "48"}, {"sp": "HDR", "t": "Κεφ. XIV", "st": "49"}, {"sp": "N", "t": "Ἑπόμενον δ’ ἂν εἴη σκέψασθαι, τίνος ἕνεκα κτίζων καὶ οἰκοδομῶν πόλιν αὐτὸς οὗτος εἰσάγεται· πλήθει γὰρ ἀνθρώπων μεγέθους δεῖ πόλεως πρὸς οἴκησιν, τρισὶ δὲ τοῖς κατ’ ἐκεῖνον οὖσι τὸν χρόνον ὑπώρειά τις ἢ μικρὸν ἄντρον αὐταρκέστατον ἦν ἐνδιαίτημα. κἀγὼ μὲν εἶπον τρισί, τὸ δ’ εἰκὸς ἑνὶ μόνῳ ἑαυτῷ· οὐδὲ γὰρ οἱ γονεῖς τοῦ δολοφονηθέντος τὴν αὐτὴν τῷ κτείναντι πόλιν ὑπέμειναν ⟨ἂν⟩ οἰκεῖν, μεῖζον ἀνδροφονίας ἄγος ἀδελφοκτονίαν ἐργασαμένῳ.", "st": "49"}, {"sp": "N", "t": "τὸ μὲν γὰρ οὐ παράδοξον μόνον ἀλλὰ καὶ παράλογον παντί τῳ δῆλον, ἕνα ἄνδρα πόλιν οἰκοδομεῖν. τίνα ἔστι τρόπον; ἀλλ’ οὐδ’ ἂν οἰκίας μέρος τὸ ἀφανέστατον, μὴ χρώμενον ὑπηρέταις ἑτέροις. ἢ ὁ αὐτὸς ἐν τῷ αὐτῷ λιθοτομεῖν ἂν δύναιτο, ὑλοτομεῖν, σίδηρον, χαλκὸν ἐργάζεσθαι, τειχῶν μέγαν κύκλον πόλει περιβάλλεσθαι, προπύλαια καὶ προτειχίσματα, ἱερὰ καὶ τεμένη καὶ στοὰς καὶ νεωσοίκους καὶ οἰκίας καὶ ὅσα ἄλλα δημόσια καὶ ἴδια ἔθος οἰκοδομεῖσθαι; καὶ ἔτι πρὸς τούτοις ὀχετοὺς κατὰ γῆν ἀναστέλλειν, στενωποὺς ἀνευρύνειν, κρήνας καὶ ὑδρορροὰς καὶ ὅσων ἄλλων πόλει δεῖ κατασκευάζεσθαι;", "st": "50"}, {"sp": "N", "t": "μήποτ’ οὖν, ἐπειδὴ ταῦτα τῆς ἀληθείας ἀπᾴδει, βέλτιον ἀλληγοροῦντας λέγειν ἐστὶν ὅτι καθάπερ πόλιν τὸ αὑτοῦ δόγμα κατασκευάζειν ὁ Κάιν ἔγνωκε.", "st": "51"}, {"sp": "HDR", "t": "Κεφ. XV", "st": "52"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν πᾶσα πόλις ἐξ οἰκοδομημάτων καὶ οἰκητόρων καὶ νόμων συνέστηκε, τὰ μὲν οἰκοδομήματά ἐστιν αὐτῷ λόγοι οἱ ἀποδεικνύντες, οἷς καθάπερ ἀπὸ τείχους πρὸς τὰς τῶν ἐναντίων ἀπομάχεται προσβολὰς πιθανὰς εὑρέσεις κατὰ τῆς ἀληθείας μυθοπλαστῶν, οἰκήτορες δὲ οἱ ἀσεβείας, ἀθεότητος, φιλαυτίας, μεγαλαυχίας, ψευδοῦς δόξης ἑταῖροι δοκησίσοφοι, τὸ πρὸς ἀλήθειαν σοφὸν οὐκ εἰδότες, ἄγνοιαν καὶ ἀπαιδευσίαν καὶ ἀμαθίαν καὶ τὰς ἄλλας ἀδελφὰς καὶ συγγενεῖς κῆρας συγκεκροτηκότες, νόμοι δὲ ἀνομίαι, ἀδικίαι, τὸ ἄνισον, τὸ ἀκόλαστον, θρασύτης, ἀπόνοια, αὐθάδεια, ἡδονῶν ἀμετρίαι, τῶν παρὰ φύσιν ἄλεκτοι ἐπιθυμίαι.", "st": "52"}, {"sp": "N", "t": "τοιαύτης πόλεως ἕκαστος τῶν ἀσεβῶν ἐν ἑαυτοῦ τῇ παναθλίᾳ ψυχῇ δημιουργὸς εὑρίσκεται, μέχρις ἂν ὁ θεὸς βουλευθεὶς (Gen. 11, 6) ταῖς σοφιστικαῖς αὐτῶν τέχναις ἀθρόαν καὶ μεγάλην ἐργάσηται σύγχυσιν. τοῦτο δ’ ἔσται, ὅταν μὴ μόνον πόλιν, ⟨ἀλλὰ⟩ καὶ πύργον οἰκοδομῶσιν, οὗ ἡ κεφαλὴ εἰς οὐρανὸν ἀφίξεται (Gen. 11, 4), τουτέστι λόγον ἑκάστου κατασκευαστικόν, ὅνπερ εἰσηγοῦνται κεφαλὴν ἔχοντα τὸ οἰκεῖον νόημα, ὃ προσαγορεύεται συμβολικῶς οὐρανός· ἀνάγκη γὰρ παντὸς λόγου κεφαλὴν καὶ τέλος εἶναι τὸν δηλούμενον νοῦν, οὗ χάριν αἱ μακραὶ διέξοδοί τε καὶ ῥήσεις ὑπὸ λογίων ἀνδρῶν εἰώθασι γίνεσθαι.", "st": "53"}, {"sp": "HDR", "t": "Κεφ. XVI", "st": "54"}, {"sp": "N", "t": "τοσοῦτον δ’ ἄρα τῆς ἀσεβείας ἐπιβεβήκασιν, ὥστ’ οὐ μόνον δι’ ἑαυτῶν ἐγείρειν τὰς τοιαύτας πόλεις ἀξιοῦσιν, ἀλλὰ καὶ τὴν φιλάρετον πληθὺν Ἰσραὴλ ἀναγκάζουσιν ἐπιστάτας καὶ διδασκάλους κακῶν ἔργων ἐπ’ αὐτοῖς χειροτονήσαντες. λέγεται γὰρ ὅτι κακωθέντες ὑπὸ τῶν ἐπιστατῶν τῷ βασιλεῖ τῆς χώρας τρεῖς πόλεις οἰκοδομοῦσι, Πειθώ, Ῥαμεσσή, Ὤν, ἥ ἐστιν Ἡλίου πόλις (Exod. 1, 11).", "st": "54"}, {"sp": "N", "t": "αὗται δὲ τροπικώτερον νοῦν, αἴσθησιν, λόγον, τὰ περὶ ἡμᾶς ὄντα, δηλοῦσιν· ἡ μὲν γὰρ Πειθὼ ὁ λόγος ἐστίν, ὅτι περὶ τοῦτον τὸ πείθειν, ἔχει δὲ ἑρμηνείαν στόμα ἐκθλῖβον, ἐπειδήπερ καὶ ὁ τοῦ φαύλου λόγος ἐξωθεῖν καὶ ἀνατρέπειν τὰ σπουδαῖα μελετᾷ.", "st": "55"}, {"sp": "N", "t": "Ῥαμεσσὴ δὲ ἡ αἴσθησις * * * καθάπερ γὰρ ὑπὸ σητὸς ὑφ’ ἑκάστης τῶν αἰσθήσεων νοῦς ἐκβιβρώσκεται καὶ διεσθίεται, σειόμενος καὶ σπαραττόμενος· αἱ γὰρ ἐπεισιοῦσαι μὴ καθ’ ἡδονὴν φαντασίαι λυπηρὸν καὶ ἐπίπονον ἀποτίκτουσι τὸν βίον.", "st": "56"}, {"sp": "N", "t": "ἡ δὲ Ὢν καλεῖται μὲν βουνός, ἔστι δὲ συμβολικῶς ὁ νοῦς· ἐπὶ γὰρ τοῦτον οἱ πάντων θησαυρίζονται λόγοι. μάρτυς δὲ καὶ ὁ νομοθέτης τὴν Ὢν Ἡλίου πόλιν προσαγορεύσας· ὥσπερ γὰρ ἀνατείλας ἥλιος τὰ κρυπτόμενα νυκτὶ ἐμφανῶς ἐπιδείκνυται, οὕτως ὁ νοῦς τὸ οἰκεῖον φῶς ἀποστέλλων πάντα καὶ τὰ σώματα καὶ τὰ πράγματα τηλαυγῶς παρασκευάζει καταλαμβάνεσθαι.", "st": "57"}, {"sp": "N", "t": "διόπερ οὐκ ἄν τις εἰπὼν ἁμάρτοι τοῦ συγκρίματος εἶναι ἡμῶν τὸν νοῦν ἥλιον, ὃς ἐν ἀνθρώπῳ τῷ βραχεῖ κόσμῳ μὴ ἀνατείλας καὶ τὸ ἴδιον φέγγος ἐκλάμψας, πολὺ σκότος τῶν ὄντων καταχέας οὐδὲν ἐᾷ προφαίνεσθαι.", "st": "58"}, {"sp": "HDR", "t": "Κεφ. XVII", "st": "59"}, {"sp": "N", "t": "τὸν βουνὸν τοῦτον ὁ ἀσκητὴς Ἰακὼβ ἐν τοῖς πρὸς Λάβαν δικαίοις μάρτυρα καλεῖ (Gen. 31, 46. 47) δογματικώτατα δηλῶν ὅτι ὁ νοῦς ἑκάστῳ μάρτυς ἐστὶν ὧν ἐν ἀφανεῖ βουλεύεται καὶ τὸ συνειδὸς ἔλεγχος ἀδέκαστος καὶ πάντων ἀψευδέστατος, * * * πρὸ τούτων τῶν πόλεων οἰκοδομεῖται.", "st": "59"}, {"sp": "N", "t": "φησὶ γὰρ τοὺς κατασκόπους ἐλθεῖν εἰς Χεβρών, ἐκεῖ δ’ εἶναι Ἀχειμὰν καὶ Σεσεὶν καὶ Θαλαμείν, γενεὰς Ἐνάχ· εἶτ’ ἐπιφέρει· “καὶ Χεβρὼν ἑπτὰ ἔτεσιν ᾠκοδομήθη πρὸ τοῦ Τάνιν Αἰγύπτου” (Num. 13, 23). φυσικώτατον ⟨τὸ⟩ τὰς ὁμωνυμίας εἴδεσι διαστέλλεσθαι. Χεβρὼν ⟨γὰρ⟩ ἑρμηνεύεται συζυγή· δισσὸν δὲ τοῦτο, ψυχῆς ἢ σώματι συνεζευγμένης ἢ πρὸς ἀρετὴν ἡρμοσμένης.", "st": "60"}, {"sp": "N", "t": "ἡ μὲν οὖν σωματικαῖς συζυγίαις ὑποβάλλουσα αὑτὴν οἰκήτορας ἔχει τοὺς λεχθέντας· ἑρμηνεύεται δὲ ὁ μὲν Ἀχειμὰν ἀδελφός μου, ὁ δὲ Σεσεὶν ἐκτός μου, ὁ δὲ Θαλαμεὶν κρεμάμενός τις· ἀνάγκη γὰρ ψυχαῖς ταῖς φιλοσωμάτοις ἀδελφὸν μὲν νομίζεσθαι τὸ σῶμα, τὰ δὲ ἐκτὸς ἀγαθὰ διαφερόντως τετιμῆσθαι· ὅσαι δὲ τοῦτον διάκεινται τὸν τρόπον, ἀψύχων ἐκκρέμανται καὶ καθάπερ οἱ ἀνασκολοπισθέντες ἄχρι θανάτου φθαρταῖς ὕλαις προσήλωνται.", "st": "61"}, {"sp": "N", "t": "ἡ δὲ τῷ καλῷ συνεζευγμένη διαφερόντων ταῖς ἀρεταῖς ἔλαχεν οἰκητόρων, οὓς τὸ διπλοῦν σπήλαιον (Gen. 23, 9) ζυγάδην κεχώρηκεν, Ἀβραὰμ Σάρραν, Ἰσαὰκ Ῥεβέκκαν, Λείαν Ἰακώβ, ἀρετὰς καὶ τοὺς ἔχοντας. ἡ Χεβρὼν αὕτη, μνήμας ἐπιστήμης ⟨καὶ⟩ σοφίας θησαυροφυλακοῦσα, προτέρα καὶ Τάνεως καὶ πάσης ἐστὶν Αἰγύπτου. πρεσβυτέραν γὰρ ἡ φύσις ψυχὴν μὲν σώματος, Αἰγύπτου, ἀρετὴν δὲ κακίας, Τάνεως – ἐντολὴ γὰρ ἀποκρίσεως ἑρμηνεύεται Τάνις – εἰργάζετο, τὸ πρεσβύτερον ἀξιώματι μᾶλλον ἢ χρόνου μήκει δοκιμάσασα.", "st": "62"}, {"sp": "HDR", "t": "Κεφ. XVIII", "st": "63"}, {"sp": "N", "t": "παρὸ καὶ τὸν Ἰσραὴλ νεώτερον ὄντα χρόνῳ πρωτόγονον υἱὸν (Exod. 4, 22) ἀξιώματι καλεῖ, διασυνιστὰς ὅτι ⟨ὁ⟩ τὸν θεὸν ὁρῶν, ἀρχεγονώτατον ὄν, τετίμηται, τοῦ ἀγενήτου γέννημα πρώτιστον, ἐκ τῆς παρὰ τοῖς θνητοῖς μισουμένης ἀρετῆς ἀποκυηθέν, ᾧ [ὁ] νόμος ἐστὶν ὡς πρεσβυτάτῳ διπλᾶ δίδοσθαι τὰ πρεσβεῖα (Deut. 21, 17).", "st": "63"}, {"sp": "N", "t": "διὰ τοῦτο καὶ ἡ ἑβδόμη τάξει μὲν ἐπιγέννημά ἐστιν ἑξάδος, δυνάμει δὲ πρεσβυτάτη παντὸς ἀριθμοῦ, μηδὲν διαφέρουσα μονάδος. δηλώσει δὲ καὶ αὐτὸς ἐν τῷ τῆς κοσμοποιίας ἐπιλόγῳ φάσκων· “καὶ κατέπαυσεν ὁ θεὸς ἐν τῇ ἡμέρα τῇ ἑβδόμῃ ἀπὸ πάντων τῶν ἔργων αὐτοῦ ὧν ἐποίησε· καὶ εὐλόγησεν ὁ θεὸς τὴν ἡμέραν τὴν ἑβδόμην καὶ ἡγίασεν αὐτήν, ὅτι ἐν αὐτῇ κατέπαυσεν ἀπὸ πάντων τῶν ἔργων αὐτοῦ ὧν ἤρξατο ὁ θεὸς ποιῆσαι” (Gen. 2, 2. 3).", "st": "64"}, {"sp": "N", "t": "εἶτ’ ἐπιλέγει· “αὕτη ἡ βίβλος γενέσεως οὐρανοῦ καὶ γῆς, ὅτε ἐγένετο, ᾗ ἡμέρᾳ ἐποίησεν ὁ θεὸς τὸν οὐρανὸν καὶ τὴν γῆν” (Gen. 2, 4). τῇ δὲ πρώτῃ ταῦτα γέγονεν, ὥστε τὴν ἑβδόμην εἰς μονάδα τὴν πρώτην καὶ ἀρχὴν τῶν ὅλων ἀναφέρεσθαι. ταῦτ’ ἐμηκύναμεν ὑπὲρ τοῦ δεῖξαι τηλαυγέστερον τὴν δόξαν, ἣν ὁ Κάιν ὥσπερ τινὰ πόλιν οἴεται δεῖν κατασκευάζειν.", "st": "65"}, {"sp": "HDR", "t": "Κεφ. XIX", "st": "66"}, {"sp": "N", "t": "Υἱὸς δὲ τοῦ Ἐνὼχ λέγεται Γαϊδάδ (Gen. 4, 18), ὃ ἑρμηνεύεται ποίμνιον, σφόδρα ἀκολούθως· τὸν γὰρ τῷ νῷ χαριζόμενον τὰ πάντα τῷ μηδὲ τὴν αὑτοῦ φύσιν ἥτις ἐστὶ καταλαβεῖν δυναμένῳ γεννᾶν ἀλόγους ἥρμοττε δυνάμεις, ἀγειρομένας εἰς ποίμνιον· οὐ γὰρ λογικῶν ἀνδρῶν τὸ δόγμα.", "st": "66"}, {"sp": "N", "t": "ποίμνη δὲ πᾶσα τὸν ἐπιστάντα οὐκ ἔχουσα ποιμένα μεγάλαις ἐξ ἀνάγκης κακοπραγίαις χρῆται, ἅτ’ οὐ δυναμένη δι’ ἑαυτῆς ἀπωθεῖσθαι μὲν τὰ βλάπτοντα, αἱρεῖσθαι δὲ τὰ ὠφελήσοντα. παρὸ καὶ Μωυσῆς εὐχόμενός φησιν· “ἐπισκεψάσθω κύριος ὁ θεὸς τῶν πνευμάτων καὶ πάσης σαρκὸς ἄνθρωπον ἐπὶ τῆς συναγωγῆς ταύτης, ὅστις ἐξελεύσεται πρὸ προσώπου αὐτῶν καὶ ὅστις εἰσελεύσεται, καὶ ὅστις ἐξάξει αὐτοὺς καὶ ὅστις εἰσάξει, καὶ οὐκ ἔσται ἡ συναγωγὴ κυρίου ὡσεὶ πρόβατα οἷς οὐκ ἔστι ποιμήν” (Num. 27, 16. 17).", "st": "67"}, {"sp": "N", "t": "ὅταν γὰρ ὁ προστάτης ἢ [ὁ] ἐπίτροπος ἢ πατὴρ ἢ ὅ τι φίλον καλεῖν τοῦ συγκρίματος ἡμῶν, ὁ ὀρθὸς λόγος, οἴχηται καταλιπὼν τὸ ἐν ἡμῖν ποίμνιον, ἀτημέλητον ἐαθὲν διόλλυται μὲν αὐτό, μεγάλη δὲ τῷ δεσπότῃ ζημία γίνεται· τὸ δ’ ἄλογον καὶ ἀπροστασίαστον θρέμμα χηρεῦσαν ἀγελάρχου τοῦ νουθετήσοντός τε καὶ παιδεύσοντος μακρὰν λογικῆς καὶ ἀθανάτου ζωῆς ἀπῴκισται.", "st": "68"}, {"sp": "HDR", "t": "Κεφ. XX", "st": "69"}, {"sp": "N", "t": "διὸ τοῦ Γαϊδὰδ υἱὸς εἶναι λέγεται Μαιήλ (Gen. 4, 18), οὗ τὸ ὄνομα μεταληφθέν ἐστιν ἀπὸ ζωῆς θεοῦ. ἐπεὶ γὰρ τὸ ποίμνιον ἄλογον, ὁ δὲ θεὸς πηγὴ λόγου, ἀνάγκη τὸν ἀλόγως βιοῦντα τῆς θεοῦ ζωῆς ἀπεσχοινίσθαι. τὸ μὲν οὖν κατὰ θεὸν ζῆν ἐν τῷ ἀγαπᾶν αὐτὸν ὁρίζεται Μωυσῆς· λέγει γὰρ ὅτι ἡ ζωή σου τὸ ἀγαπᾶν τὸν ὄντα (Deut. 30, 19. 20).", "st": "69"}, {"sp": "N", "t": "τοῦ δ’ ἐναντίου βίου παράδειγμα τίθεται τὸν ἐπιτυχόντα τοῦ κλήρου τράγον· “στήσει γὰρ αὐτὸν” φησί “ζῶντα ἐναντίον κυρίου τοῦ ἐξιλάσασθαι ἐπ’ αὐτοῦ, ὥστε ἐξαποστεῖλαι αὐτὸν εἰς τὴν ἀποπομπήν” (Lev. 16, 10), ἄγαν ἐξητασμένως·", "st": "70"}, {"sp": "N", "t": "ὡς γὰρ ἡδονῶν ἀπεχομένους πρεσβύτας εὖ φρονῶν οὐκ ἄν τις ἀποδέξαιτο, ὅτι τὸ γῆρας, ἡ μακρὰ καὶ ἀνίατος νόσος, τοὺς τῶν ὀρέξεων ἐχάλασέ τε καὶ ἔλυσε τόνους, ἐπαίνου δ’ ἂν ἀξιώσειε τοὺς ἡβῶντας, ὅτι φλεγούσης τῆς ἐπιθυμίας ὑπὸ τῆς κατὰ τὴν ἡλικίαν ἀκμῆς ὅμως σβεστηρίων ὀργάνων τῶν κατὰ παιδείαν λόγων εὐπορήσαντες τὸν πολὺν φλογμὸν ἅμα καὶ βρασμὸν τῶν παθῶν ἐπεκούφισαν, οὕτως οἷς μὲν οὐδὲν νόσημα, οἷα ἐκ πονηρᾶς φιλεῖ διαίτης ἐπανίστασθαι, ἐλάττων ἔπαινος ἕπεται, ὅτι κατὰ φύσεως εὐμοιρίαν ἀπροαιρέτως ἐχρήσαντο εὐτυχίᾳ, οἷς δ’ ἐξεγερθὲν ἀντιστατεῖ, μείζων, εἰ δὴ διερεισάμενοι καθελεῖν αὐτὸ βουληθεῖέν τε καὶ δυνηθεῖεν.", "st": "71"}, {"sp": "N", "t": "τὰ γὰρ ἡδονῆς ὁλκοῦ δελέατα αὐστηρῷ τόνῳ καθελεῖν ἰσχῦσαι τὸν ἐφ’ ἑκουσίοις ἔχει κατορθώμασιν ἔπαινον. ἐὰν οὖν τούτων εὐδαίμονα κλῆρον ἀπολαχόντα μηδέν, ζῇ δὲ ἐν ἡμῖν τὰ ἀποπομπαῖα νοσήματα καὶ ἀρρωστήματα, σπουδάζωμεν αὐτὰ ἀνατρέπειν καὶ καταβάλλειν· τὸ γὰρ ἐξιλάσασθαι ἐπ’ αὐτῶν τοιοῦτόν ἐστιν, ὁμολογῆσαι ὅτι ἔχοντες αὐτὰ ἐν ψυχῇ ζῶντα καὶ περιόντα οὐκ ἐνδίδομεν, ἀλλ’ ἀντιβάντες ἅπασι καρτερῶς ἀπομαχόμεθα, μέχρις ἂν παντελῶς ἀποδιοπομπησώμεθα.", "st": "72"}, {"sp": "HDR", "t": "Κεφ. XXI", "st": "73"}, {"sp": "N", "t": "τί δ’ ἕπεται τῷ μὴ κατὰ βούλημα τὸ τοῦ θεοῦ ζῶντι ἢ θάνατος ὁ ψυχῆς; οὗτος δὲ ὀνομάζεται Μαθουσάλα, ὃς ἑρμηνευθεὶς ἦν ἀποστολὴ θανάτου. διὸ τοῦ Μαιὴλ υἱός ἐστι (Gen. 4, 18), τοῦ τὸν ἴδιον βίον ἀπολελοιπότος, ᾧ τὸ ἀποθνῄσκειν ἐπιπέμπεται, ψυχῆς θάνατος, ἣ κατὰ πάθος ἄλογόν ἐστιν αὐτῆς μεταβολή.", "st": "73"}, {"sp": "N", "t": "τοῦτο μέντοι τὸ πάθος ὅταν κυοφορήσῃ, μετὰ χαλεπῶν ὠδίνων νοσήματα καὶ ἀρρωστήματα ἔτεκεν ἀνίατα, ὑφ’ ὧν ἰλυσπωμένη ταπεινοῦται καὶ κάμπτεται· πιέζει γὰρ αὐτὴν ἕκαστον ἐπιφέρον ἄχθος ἀνήνυτον, ὡς μηδ’ ἀνακῦψαι δύνασθαι. τοῦθ’ ἅπαν ὠνόμασται Λάμεχ· ἑρμηνείαν γὰρ ἔχει ταπείνωσιν, ἵν’ εἰκότως τοῦ Μαθουσάλα γένηται ὁ Λάμεχ υἱός (Gen. 4, 18), πάθους τοῦ περὶ ψυχὴν θανάτου ταπεινὸν καὶ ὑπεῖκον, ἀλόγου ὁρμῆς ἔκγονον ἀρρώστημα.", "st": "74"}, {"sp": "HDR", "t": "Κεφ. XXII", "st": "75"}, {"sp": "N", "t": "“Ἔλαβε δ’ ἑαυτῷ Λάμεχ δύο γυναῖκας· ὄνομα τῇ μιᾷ Ἀδά, καὶ ὄνομα τῇ δευτέρᾳ Σελλά” (Gen. 4, 19). πᾶν ὅ τι ἂν ἑαυτῷ λαμβάνῃ φαῦλος, πάντως ἐστὶν ἐπίληπτον, ἅτε γνώμῃ δυσκαθάρτῳ μιαινόμενον· καὶ γὰρ ἔμπαλιν αἱ τῶν σπουδαίων ἑκούσιοι πράξεις ἐπαινεταὶ πᾶσαι. διὸ νῦν μὲν ὁ Λάμεχ ἑαυτῷ γυναῖκας αἱρούμενος κακὰ μέγιστα αἱρεῖται, αὖθις ⟨δ’⟩ Ἀβραάμ, Ἰακώβ, Ἀαρὼν ἑαυτοῖς λαμβάνοντες ἀγαθοῖς οἰκείοις συνέρχονται.", "st": "75"}, {"sp": "N", "t": "λέγει ⟨γὰρ⟩ ἐπὶ μὲν τοῦ Ἀβραὰμ οὕτως· “καὶ ἔλαβον Ἀβραὰμ καὶ Ναχὼρ ἑαυτοῖς γυναῖκας· ὄνομα τῇ γυναικὶ Ἀβραὰμ Σάρρα” (Gen. 11, 29), ἐπὶ ⟨δὲ⟩ τοῦ Ἰακώβ· “ἀναστὰς ἀπόδραθι εἰς τὴν Μεσοποταμίαν εἰς τὸν οἶκον Βαθουὴλ πατρὸς τῆς μητρός σου, καὶ λάβε σεαυτῷ ἐκεῖθεν γυναῖκα ἐκ τῶν θυγατέρων Λάβαν ἀδελφοῦ τῆς μητρός σου” (Gen. 28, 2), ἐπὶ δὲ τοῦ Ἀαρών· “ἔλαβε δὲ Ἀαρὼν τὴν Ἐλισάβετ, θυγατέρα Ἀμιναδάμ, ἀδελφὴν Ναασσών, ἑαυτῷ γυναῖκα” (Exod. 6, 23).", "st": "76"}, {"sp": "N", "t": "Ἰσαὰκ δὲ καὶ Μωυσῆς λαμβάνουσι μέν, οὐ δι’ ἑαυτῶν δὲ λαμβάνουσιν, ἀλλ’ ὁ μὲν Ἰσαὰκ ὅτε εἰσῆλθεν εἰς τὸν οἶκον τῆς μητρὸς λαβεῖν λέγεται (Gen. 24, 67), Μωυσῇ δὲ ὁ ἄνθρωπος παρ’ ᾧ κατῴκησε τὴν θυγατέρα Σεπφώραν ἐκδίδοται (Exod. 2, 21).", "st": "77"}, {"sp": "HDR", "t": "Κεφ. XXIII", "st": "78"}, {"sp": "N", "t": "τούτων δ’ οὐ παρέργως αἱ διαφοραὶ παρὰ τῷ νομοθέτῃ μεμήνυνται. τοῖς μὲν γὰρ ἀσκηταῖς προκόπτουσι καὶ βελτιουμένοις ἡ ἑκούσιος αἵρεσις τἀγαθοῦ μαρτυρεῖται, ἵνα μηδ’ ὁ πόνος ἀστεφάνωτος ἀφεθῇ· τοῖς δ’ αὐτοδιδάκτου καὶ αὐτομαθοῦς σοφίας ἀξιωθεῖσιν ἕπεται τὸ μὴ δι’ ἑαυτῶν παρὰ θεοῦ δ’ ἐγγυᾶσθαι λόγον καὶ λαμβάνειν τὴν σοφῶν σύμβιον ἐπιστήμην.", "st": "78"}, {"sp": "N", "t": "ὁ δὲ τῶν ἀνθρωπίνων ἀπορριφείς, ὁ ταπεινὸς καὶ χαμαίζηλος Λάμεχ, προτέραν Ἀδὰ ἄγεται γυναῖκα, ἥτις ἑρμηνεύεται μαρτυρία, προξενήσας ἑαυτῷ αὐτὸς τὸν γάμον· οἴεται γὰρ τὴν κατὰ τὰς εὐθίκτους ἐπιβολὰς λείαν κίνησιν καὶ διέξοδον τοῦ νοῦ, μηδενὸς [τῶν] εἰς εὐμαρῆ κατάληψιν κωλυσιεργοῦντος, ἀγαθὸν εἶναι πρῶτον ἀνθρώπῳ.", "st": "79"}, {"sp": "N", "t": "τί γὰρ ἂν εἴη, φησί, κρεῖττον τοῦ τὰς ἐννοίας, τὰς διανοήσεις, τὰς εἰκασίας, τοὺς στοχασμούς, συνόλως τὰς βουλάς, τὸ λεγόμενον ἀρτίοις ποσὶ βαίνειν, ὡς ἐπὶ τὸ τέλος ἀπταίστως προσέρχεσθαι, μαρτυρουμένης ἐν ἅπασι ⟨τοῖς⟩ λεχθεῖσι διανοίας; ἐγὼ δ’, εἰ μέν τις εὐθυβόλῳ καὶ εὐθίκτῳ γνώμῃ πρὸς μόνα χρῆται τὰ καλά, τοῦτον εὐδαίμονα γράφω διδασκάλῳ τῷ νόμῳ χρώμενος· καὶ γὰρ αὐτὸς ἄνδρα ἐπιτυγχάνοντα εἶπε τὸν Ἰωσήφ, οὐκ ἐν ἅπασιν, ἀλλ’ ἐν οἷς ὁ θεὸς τὸ εὐοδεῖν ἐχαρίζετο (Gen. 39, 2)· δωρεαὶ δ’ αἱ τοῦ θεοῦ καλαὶ πᾶσαι.", "st": "80"}, {"sp": "N", "t": "εἰ δέ τις τῷ τῆς φύσεως εὐστόχῳ καὶ εὐτρόχῳ μὴ πρὸς τὰ ἀστεῖα μόνον, ἀλλὰ καὶ πρὸς τὰ ἐναντία κέχρηται τὰ διάφορα ἐξαδιαφορῶν, κακοδαιμονιζέσθω. ἐν γοῦν ἀρᾶς εἴδει λέγεται κατὰ τὸν τῆς συγχύσεως τόπον, ὅτι “οὐκ ἐκλείψει ἐξ αὐτῶν πάνθ’ ὅσα ἂν ἐπιθῶνται ποιεῖν” (Gen. 11, 6)· ὄντως γὰρ ἀνήκεστός ἐστι συμφορὰ ψυχῆς εὐοδεῖν οἷς ἂν ἐπιθῆται, καὶ τὰ αἴσχιστα.", "st": "81"}, {"sp": "N", "t": "ἐγὼ δ’ ἂν εὐξαίμην, εἴ ποτε διανοηθείην ἀδικεῖν, ἐπιλιπεῖν τἀδικεῖν, καὶ εἴπερ ζῆν ἀνάνδρως, ἐπιλιπεῖν τὸ ἀκολασταίνειν, καὶ εἰ θρασέως μέντοι καὶ πανούργως, ἔνδειαν θρασύτητος καὶ πανουργίας γενέσθαι παντελῆ· εἰ μὴ καὶ τοῖς κλέπτειν ἢ μοιχεύειν ἢ ἀνδροφονεῖν ἐγνωκόσιν οὐκ ἔστιν ἄμεινον ἐπιδεῖν τούτων ἕκαστον ἐκλελοιπὸς καὶ διεφθαρμένον.", "st": "82"}, {"sp": "HDR", "t": "Κεφ. XXIV", "st": "83"}, {"sp": "N", "t": "τὴν οὖν Ἀδὰ παραίτησαι, διάνοια, τὴν μαρτυροῦσάν τε τοῖς φαύλοις καὶ μαρτυρουμένην ἐν ταῖς πρὸς ἕκαστα αὐτῶν ἐπιβολαῖς. εἰ δὲ κοινωνὸν αὐτὴν ἀξιώσεις ἔχειν, μέγιστον ἀποτέξεταί σοι κακόν, τὸν Ἰωβήλ (Gen. 4, 20), ὃς ἑρμηνεύεται μεταλλοιῶν· εἰ γὰρ τῇ μαρτυρίᾳ χαίρεις ὧν ἂν τύχῃ, στρέφειν καὶ ἀνακυκλεῖν ἕκαστα βουλήσῃ, τοὺς παγέντας ὑπὸ τῆς φύσεως τοῖς πράγμασιν ὅρους μετατιθείς.", "st": "83"}, {"sp": "N", "t": "σφόδρα δὲ καὶ Μωυσῆς ἀχθόμενος τοῖς τοιούτοις καταρᾶται λέγων· “ἐπικατάρατος ὁ μετατιθεὶς ὅρια τοῦ πλησίον” (Deut. 27, 17). καλεῖ δὲ πλησίον καὶ ἐγγὺς τἀγαθόν· οὐ γὰρ ἀναπτῆναι, φησίν, εἰς οὐρανὸν οὐδὲ πέραν θαλάσσης ἀφικέσθαι δεῖ κατὰ ζήτησιν τοῦ καλοῦ· ἐγγὺς γὰρ καὶ πλησίον ἵστασθαι ἑκάστῳ.", "st": "84"}, {"sp": "N", "t": "καὶ τριχῇ γε αὐτὸ διαιρεῖ φυσικώτατα· “ἐν γὰρ τῷ στόματί σου” φησίν “ἐστὶ καὶ ἐν τῇ καρδίᾳ καὶ ἐν ταῖς χερσί” (Deut. 30, 11‑14), τοῦτο δὴ ἐν λόγοις, ἐν βουλαῖς, ἐν πράξεσι· μέρη γὰρ τοῦ ἀγαθοῦ ταῦτα, ἐξ ὧν πέφυκε πήγνυσθαι, ὡς ἥ γε ἑνὸς ἔνδεια οὐκ ἀτελὲς μόνον ἀπεργάζεται τὸ πᾶν, ἀλλὰ καὶ συνόλως ἀναιρεῖ.", "st": "85"}, {"sp": "N", "t": "τί γὰρ ὄφελος λέγειν μὲν τὰ βέλτιστα, διανοεῖσθαι δὲ καὶ πράττειν τὰ αἴσχιστα; σοφιστῶν οὗτος ὁ τρόπος· τοὺς γὰρ περὶ φρονήσεως καὶ καρτερίας ἀπομηκύνοντες λόγους τὰ ὦτα καὶ τῶν σφόδρα διψώντων ἀκοῆς ἀποκναίουσιν, ἐν δὲ ταῖς βουλαῖς καὶ ταῖς κατὰ τὸν βίον πράξεσιν εὑρίσκονται διαμαρτάνοντες.", "st": "86"}, {"sp": "N", "t": "τί δ’ ὄφελος ἃ μὲν χρὴ διανοεῖσθαι, ἔργοις δὲ ἀτόποις καὶ λόγοις χρῆσθαι, διὰ μὲν τῶν λόγων τοὺς ἀκούοντας, διὰ δὲ τῶν ἔργων τοὺς ὑπομένοντας ζημιοῦντας; πράττειν γε μὴν τἄριστα οὐ σὺν διανοίᾳ καὶ λόγῳ πάλιν ὑπαίτιον· τὸ γὰρ ἄνευ τούτων τῆς ἀκουσίου μερίδος ὂν οὐδαμῇ οὐδαμῶς ἐπαινετόν.", "st": "87"}, {"sp": "N", "t": "εἰ δέ τινι ἐξεγένετο καθάπερ λύραν ἁρμόσασθαι τοὺς τοῦ ἀγαθοῦ πάντας ἤχους καὶ συνῳδὸν ἀποφῆναι λόγον μὲν διανοίᾳ, διάνοιαν δὲ ἔργῳ, τέλειος καὶ πρὸς ἀλήθειαν εὐάρμοστος ὁ τοιοῦτος ἂν νομίζοιτο· ὥσθ’ ὁ μετατιθεὶς ὅρους τοῦ καλοῦ δικαίως ἐπάρατος ἔστι τε καὶ λέγεται.", "st": "88"}, {"sp": "HDR", "t": "Κεφ. XXV", "st": "89"}, {"sp": "N", "t": "τοὺς δ’ ὅρους τούτους οὐχ ἡ καθ’ ἡμᾶς γένεσις ἔστησεν, ἀλλ’ οἱ πρὸ ἡμῶν καὶ παντὸς τοῦ γεώδους πρεσβύτεροι λόγοι καὶ θεῖοι· καθὰ καὶ ὁ νόμος δεδήλωκεν ἐπισκήπτων ἡμῶν ἑκάστῳ μὴ κιβδηλεύειν τὸ ἀρετῆς νόμισμα ἐν τούτοις· “οὐ μετακινήσεις ὅρια τοῦ πλησίον, ἃ ἔστησαν οἱ πατέρες σου” (Deut. 19, 14), καὶ ἐν ἑτέροις· “ἐπερώτησον τὸν πατέρα σου καὶ ἀναγγελεῖ σοι, τοὺς πρεσβυτέρους σου καὶ ἐροῦσί σοι· ὅτε διεμέριζεν ὁ ὕψιστος ἔθνη, ὡς διέσπειρεν υἱοὺς Ἀδάμ, ἔστησεν ὅρια ἐθνῶν κατὰ ἀριθμὸν ἀγγέλων θεοῦ· καὶ ἐγένετο μερὶς κυρίου λαὸς αὐτοῦ Ἰακώβ, σχοίνισμα κληρονομίας αὐτοῦ Ἰσραήλ” (Deut. 32, 7‑9).", "st": "89"}, {"sp": "N", "t": "ἆρ’ οὖν ἐὰν πύθωμαι τοῦ γεννήσαντος καὶ θρέψαντός με πατρὸς ἢ τῶν ἐκείνου μὲν ἡλικιωτῶν, ἐμοῦ δὲ πρεσβυτέρων, ἦ διένειμεν ἔθνη ὁ θεὸς ἢ ἔσπειρεν ἢ ᾤκισεν, ἀποκρινοῦνταί μοι παγίως, ὥσπερ τῷ μερισμῷ παρηκολουθηκότες ἐκείνῳ; οὐ μὲν οὖν, ἀλλὰ φήσουσιν ὅτι καὶ ἡμεῖς ἐφ’ ἡλικίας παρὰ τῶν γονέων καὶ ἔτι ἀρχαιοτέρων φιλοπευστήσαντες οὐδὲν σαφὲς ἀνεμάθομεν· οὐδὲν γὰρ εἶχον ὅ τι διδάξουσιν ἡμᾶς καὶ αὐτοὶ πάλιν ἄλλων ἀξιώσαντες γενέσθαι ἐπιστημόνων ἀνεπιστήμονες γνώριμοι.", "st": "90"}, {"sp": "HDR", "t": "Κεφ. XXVI", "st": "91"}, {"sp": "N", "t": "μήποτ’ οὖν πατέρα μὲν τῆς ψυχῆς ἡμῶν τὸν ὀρθὸν λόγον καλεῖ, πρεσβυτέρους δὲ τοὺς ἑταίρους αὐτοῦ καὶ φίλους. οὗτοι τῆς ἀρετῆς τοὺς ὅρους ἐπήξαντο πρῶτοι, πρὸς οὓς ἄξιον φοιτῆσαι μαθήσεως καὶ διδασκαλίας ἕνεκα τῶν ἀναγκαίων. τὰ δ’ ἀναγκαῖα ταῦτα· ὁπότε ὁ θεὸς διένεμε καὶ διετείχιζε τὰ τῆς ψυχῆς ἔθνη τὰ ὁμόφωνα τῶν ἀλλογλώττων διιστὰς καὶ διοικίζων, τούς τε γῆς παῖδας ἔσπειρε καὶ ἐξετόξευσεν ἀφ’ ἑαυτοῦ, οὓς Ἀδὰμ ὠνόμασεν υἱούς, τότε τῶν ἀρετῆς ἐκγόνων τοὺς ὅρους ἔστησεν ἰσαρίθμους ἀγγέλοις· ὅσοι γὰρ θεοῦ λόγοι, τοσαῦτα ἀρετῆς ἔθνη τε καὶ εἴδη.", "st": "91"}, {"sp": "N", "t": "τίνες ⟨δ’⟩ αἱ τῶν ἀγγέλων αὐτοῦ λήξεις καὶ τίς ἡ τοῦ παντάρχου καὶ ἡγεμόνος ἀποκεκληρωμένη μοῖρα; τῶν μὲν οὖν ὑπηρετῶν αἱ ἐν εἴδει ἀρεταί, τοῦ δὲ ἡγεμόνος τὸ ἐπίλεκτον γένος Ἰσραήλ· ὁ γὰρ ὁρῶν τὸν θεὸν ὑπὸ ἐκπρεπεστάτου κάλλους ἀγόμενος τῷ ὁρωμένῳ προσκεκλήρωταί τε καὶ μεμέρισται.", "st": "92"}, {"sp": "N", "t": "πῶς οὖν οὐκ ἐπιπληκτέος Ἰωβήλ, ὃς ἑλλάδι γλώττῃ μεταλλοιῶν καλεῖται τὰς φύσεις τῶν πραγμάτων ἢ μεταποιῶν; τὰ γὰρ φρονήσεως καὶ καρτερίας καὶ δικαιοσύνης καὶ τῆς ἄλλης ἀρετῆς κάλλη θεοειδέστατα τύποις ἐναντίοις ἀφροσύνης, [καὶ] ἀκρασίας, ἀδικίας, ἁπάσης κακίας μετεχάραττεν ἀφανίζων τὰ ἐνσημανθέντα πρότερον.", "st": "93"}, {"sp": "HDR", "t": "Κεφ. XXVII", "st": "94"}, {"sp": "N", "t": "αἰεὶ γὰρ ἐπιτεθειμέναι δεύτεραι σφραγῖδες τοὺς τῶν προτέρων τύπους διαφθείρουσιν. ὁ δέ γε νόμος τοσοῦτον δεῖ κακὰ ἀγαθῶν ἐπιτρέπειν ἀντικαταλλάττεσθαι, ὥστ’ οὐδὲ καλὰ πονηρῶν ἐᾷ, πονηρὰ οὐ τὰ φαῦλα παραλαμβάνων – ἐπεὶ τοῦτό γε εὔηθες μὴ προΐεσθαι τὰ κακὰ ὑπὲρ κτήσεως τῶν ἀμεινόνων – , ἀλλὰ τὰ καματηρὰ καὶ ἐπίπονα, ἅπερ Ἀττικοὶ τὴν πρώτην ὀξυτονοῦντες συλλαβὴν καλοῦσι πόνηρα.", "st": "94"}, {"sp": "N", "t": "ἔστι δὲ τὸ διάταγμα τοιοῦτο· “πᾶν ὃ ἐὰν ἔλθῃ ἐν τῷ ἀριθμῷ ὑπὸ τὴν ῥάβδον, τὸ δέκατον ἅγιον τῷ κυρίῳ. οὐκ ἀλλάξεις καλὸν πονηρῷ· ἐὰν δὲ ἀλλάξῃς, αὐτό τε καὶ τὸ ἄλλαγμα ἔσται ἅγια” (Lev. 27, 32‑33). καίτοι πῶς τό γε πονηρὸν γένοιτ’ ἂν ἅγιον; ἀλλ’, ὅπερ ἔφην, τὸ ἐπίπονον ἀλλ’ οὐ φαῦλον παρείληπται, ὥστε τοιοῦτον εἶναι τὸ δηλούμενον· τέλειον μὲν ἀγαθόν ἐστι τὸ καλόν, ἀτελὲς δὲ ὠφέλιμον πόνος. ἐὰν οὖν τὸ παντελὲς κτήσῃ, μηκέτι ζήτει τὸ ἐνδέον· εἰ δὲ προσυπερβάλλων ἐθελήσεις ἔτι πονεῖν, ἴσθ’ ὅτι δόξεις μὲν ἑνὸς ἓν ἀντικαταλλάττεσθαι, κτήσῃ δὲ πρὸς ἀλήθειαν ἀμφότερα· ἑκάτερον γὰρ εἰ καὶ ἰσότιμον, ἀλλ’ οὐ τὸ πάντως ἅγιόν ἐστιν.", "st": "95"}, {"sp": "HDR", "t": "Κεφ. XXVIII", "st": "96"}, {"sp": "N", "t": "ἅγιον δὲ πρᾶγμα δοκιμάζεται διὰ τριῶν μαρτύρων, ἀριθμοῦ μέσου, παιδείας, ἀριθμοῦ τελείου. διὸ λέγεται· “πᾶν ὃ ἐὰν ἔλθῃ ἐν τῷ ἀριθμῷ ὑπὸ τὴν ῥάβδον, τὸ δέκατον ἅγιον”. τὸ μὲν γὰρ ἀπαξιωθὲν ἀριθμοῦ βέβηλον, οὐχ ἅγιον, τὸ δὲ καταριθμηθὲν ἅτε ἐγκεκριμένον ἤδη δόκιμον. τὸν γοῦν ὑπὸ Ἰωσὴφ ἐν Αἰγύπτῳ συναχθέντα σῖτόν φησιν ὁ νόμος μὴ δυνηθῆναι ἀριθμηθῆναι, καὶ ἐπιφέρει· “οὐ γὰρ ἦν ἀριθμός” (Gen. 41, 49), ἐπειδὴ τὰ τοῦ σώματος καὶ τῶν Αἰγυπτίων παθῶν θρεπτικὰ οὐκ ἄξια συνόλως ἀριθμεῖσθαι.", "st": "96"}, {"sp": "N", "t": "ἡ δὲ ῥάβδος παιδείας σύμβολον· ἄνευ γὰρ τοῦ δυσωπηθῆναι καὶ περὶ ἐνίων ἐπιπληχθῆναι νουθεσίαν ἐνδέξασθαι καὶ σωφρονισμὸν ἀμήχανον. δεκὰς δὲ τῆς κατὰ προκοπὴν τελειώσεως πίστις, ἀφ’ ἧς ὅσιον ἀπάρχεσθαι τῷ τέξαντι, τῷ παιδεύσαντι, τῷ τὰ ἐλπισθέντα τελεσφορήσαντι.", "st": "97"}, {"sp": "HDR", "t": "Κεφ. XXIX", "st": "98"}, {"sp": "N", "t": "ταῦτα ἀποχρώντως λελέχθω περὶ τοῦ μεταλλοιοῦντος καὶ τὸ ἀρχαῖον νόμισμα κιβδηλεύοντος, ὃν καὶ πατέρα ὀνομάζει κατοικούντων ἐν σκηναῖς κτηνοτρόφων (Gen. 4, 20). κτήνη μὲν οὖν εἰσιν αἱ ἄλογοι αἰσθήσεις, κτηνοτρόφοι δ’ οἱ φιλήδονοι καὶ φιλοπαθεῖς τροφὰς παρέχοντες αὐταῖς τὰ ἐκτὸς αἰσθητά, μακρὰν διεστηκότες ποιμένων. οἱ μὲν γὰρ ἀρχόντων τρόπον τὰ πλημμελῶς ζῶντα τῶν θρεμμάτων κολάζουσιν, οἱ δ’ ἑστιατόρων τροφὰς ἀφθόνους παρασκευάζοντες ἄδειαν ἁμαρτημάτων παρέχουσιν· ἀνάγκη γὰρ εὐθὺς τὴν ἀπληστίας καὶ κόρου θυγατέρα γεννᾶσθαι ὕβριν.", "st": "98"}, {"sp": "N", "t": "πατὴρ οὖν ἐστιν εἰκότως ⟨ὁ⟩ ἅπαντα μεταχαράττων καὶ μεταποιῶν τὰ καλὰ τῶν τὸ αἰσθητὸν καὶ ἄψυχον ἅπαν ἐζηλωκότων· εἰ γὰρ τὰς ἀσωμάτους ⟨καὶ⟩ νοητὰς φύσεις μετεδίωκε, τοὺς ὁρισθέντας ὑπὸ τῶν πρεσβυτέρων ὅρους ἐφύλαττεν ἄν, οὓς ὑπὲρ ἀρετῆς ὥρισαν ἕκαστον αὐτῆς εἶδος οἰκείῳ τύπῳ χαράξαντες.", "st": "99"}, {"sp": "HDR", "t": "Κεφ. XXX", "st": "100"}, {"sp": "N", "t": "Τοῦ δ’ Ἰωβὴλ ἀδελφὸν εἶναί φησι τὸν Ἰουβάλ (Gen. 4, 21). ἑρμηνεύεται δὲ καὶ οὗτος μετακλίνων διὰ συμβόλου, ὁ κατὰ προφορὰν λόγος· φύσει γὰρ οὗτος διανοίας ἀδελφός ἐστι. τὸν δὲ τοῦ μεταποιοῦντος νοῦ τὰ πράγματα λόγον μετακλίνοντα σφόδρα δεόντως ὠνόμασε· συμβαίνει γὰρ τρόπον τινὰ καὶ ἐπαμφοτερίζειν καθάπερ ἐπὶ πλάστιγγος ἀντιρρέπον ἢ ὥσπερ θαλαττεῦον σκάφος ὑπὸ πολλοῦ κλύδωνος πρὸς ἑκάτερον τοῖχον ἀποκλῖνον· βέβαιον γὰρ ἢ σταθηρὸν οὐδὲν ὁ ἄφρων λέγειν ἔμαθε.", "st": "100"}, {"sp": "N", "t": "Μωυσῆς δὲ οὔτ’ εἰς δεξιὰ οὔτ’ εἰς ἀριστερὰ οὐδ’ ὅλως εἰς μέρη τοῦ γηίνου Ἐδὼμ ἀποκλίνειν οἴεται δεῖν, τῇ δὲ μέσῃ ὁδῷ παρέρχεσθαι, ἣν κυριώτατα καλεῖ βασιλικήν (Num. 20, 17). ἐπειδὴ γὰρ πρῶτος καὶ μόνος τῶν ὅλων βασιλεὺς ὁ θεός ἐστι, καὶ ἡ πρὸς αὐτὸν ἄγουσα ὁδὸς ἅτε βασιλέως οὖσα εἰκότως ὠνόμασται βασιλική. ταύτην δ’ ἡγοῦ φιλοσοφίαν, οὐχ ἣν μέτεισιν ὁ νῦν ἀνθρώπων σοφιστικὸς ὅμιλος – λόγων γὰρ οὗτοι τέχνας μελετήσαντες κατὰ τῆς ἀληθείας τὴν πανουργίαν σοφίαν ἐκάλεσαν ἔργῳ μοχθηρῷ θεῖον ἐπιφημίσαντες ὄνομα – , ἀλλ’ ἣν ὁ ἀρχαῖος ἀσκητῶν θίασος διήθλει, τὰς τιθασοὺς τῆς ἡδονῆς γοητείας ἀποστρεφόμενος, ἀστείως καὶ αὐστηρῶς χρώμενος τῇ τοῦ καλοῦ μελέτῃ.", "st": "101"}, {"sp": "N", "t": "τὴν βασιλικὴν γοῦν ταύτην ὁδόν, ἣν ἀληθῆ καὶ γνήσιον ἔφαμεν εἶναι φιλοσοφίαν, ὁ νόμος καλεῖ θεοῦ ῥῆμα καὶ λόγον. γέγραπται γάρ· “οὐκ ἐκκλινεῖς ἀπὸ τοῦ ῥήματος οὗ ἐγὼ ἐντέλλομαί σοι σήμερον δεξιὰ οὐδὲ ἀριστερά” (Deut. 28, 14)· ὥστε ἐμφανῶς ἐπιδεδεῖχθαι ὅτι ταὐτόν ἐστι τῇ βασιλικῇ ὁδῷ τὸ θεοῦ ῥῆμα, εἴγε προτρέπει μήτ’ ἀπὸ τῆς βασιλικῆς ὁδοῦ μήτ’ ἀπὸ τοῦ ῥήματος, ὡς συνωνύμων ὄντων, ἀποκλίνοντας ὀρθῇ διανοίᾳ τὴν ἐπ’ εὐθείας ἄγουσαν ἀτραπὸν μέσην τε καὶ λεωφόρον βαδίζειν.", "st": "102"}, {"sp": "HDR", "t": "Κεφ. XXXI", "st": "103"}, {"sp": "N", "t": "“Ὁ δὲ Ἰουβὰλ οὗτος” φησίν “ἐστὶ πατὴρ ὁ καταδείξας ψαλτήριον καὶ κιθάραν” (Gen. 4, 21). πατέρα μουσικῆς καὶ τῶν κατὰ μουσικὴν πάντων ὀργάνων τὸν γεγωνὸν λόγον προσφυέστατα καλεῖ· τὸ γὰρ φωνητήριον ὄργανον ζῴοις ἡ φύσις πρῶτον καὶ τελειότατον ἐργασαμένη πάσας αὐτῷ τὰς ἁρμονίας καὶ τὰ γένη τῶν μελῳδιῶν εὐθὺς ἐχαρίζετο, ἵν’ ᾖ τοῖς ἐκ τέχνης μέλλουσι δημιουργεῖσθαι προειργασμένον παράδειγμα.", "st": "103"}, {"sp": "N", "t": "[καὶ] καθάπερ γὰρ τὸ οὖς ἡμῶν κύκλους ἐν κύκλοις, ἐλάττους ἐν μείζοσι, γράφουσα σφαιρικὸν ἐτόρνευε τοῦ τὴν προσιοῦσαν φωνὴν μὴ χεομένην ἔξω σκεδάννυσθαι, εἴσω δ’ ὑπὸ τῶν κύκλων συναγομένην καὶ σφιγγομένην οἷα διαχεομένην τὴν ἀκοὴν εἰς τὰς τοῦ ἡγεμονικοῦ δεξαμενὰς ἐπαντλεῖσθαι – καὶ τοῦτ’ εὐθὺς ἦν παράδειγμα θεάτρων τῶν κατὰ πόλεις εὐδαίμονας· πρὸς ⟨γὰρ⟩ τὸ ὤτων σχῆμα ἄκρως ἡ θεάτρων κατασκευὴ μεμίμηται – , οὕτως καὶ τὴν τραχεῖαν ἀρτηρίαν ἡ τὰ ζῷα φύσις διαπλάσασα ὥσπερ μουσικὸν κανόνα τείνασα τὰ ἐναρμόνια καὶ χρωματικὰ καὶ διατονικὰ γένη συνυφαίνουσα κατὰ τὰς τῶν συνημμένων καὶ διεζευγμένων μελῳδιῶν παμπληθεῖς ποικιλίας παντὸς ὀργάνου μουσικοῦ παράδειγμα ἱδρύετο.", "st": "104"}, {"sp": "HDR", "t": "Κεφ. XXXII", "st": "105"}, {"sp": "N", "t": "ὅσα γοῦν αὐλοὶ καὶ λύραι καὶ τὰ παραπλήσια μελῳδοῦσι, τῆς ἀηδόνων ἢ κύκνων μουσικῆς τοσοῦτον ἀπολείπεται, ὅσον ἀπεικόνισμα καὶ μίμημα ἀρχετύπου παραδείγματος, φθαρτὸν εἶδος ἀφθάρτου γένους. τὴν μὲν γὰρ ἀνθρώπων μουσικὴν οὐδενὶ τῶν ἄλλων συγκρίνειν ἄξιον ἔχουσαν γέρας ἐξαίρετον, ᾧ τετίμηται, τὴν ἔναρθρον σαφήνειαν.", "st": "105"}, {"sp": "N", "t": "τὰ μὲν γὰρ ἄλλα τῇ περὶ τὴν φωνὴν κλάσει χρώμενα καὶ ταῖς ἐπαλλήλοις τῶν τόνων μεταβολαῖς ἀκοὰς αὐτὸ μόνον ἡδύνει, ὁ δ’ ἄνθρωπος, ὥσπερ πρὸς τὸ λέγειν, οὕτως καὶ πρὸς τὸ ᾄδειν ἀρθρωθεὶς ὑπὸ φύσεως ἑκάτερον, ἀκοήν τε καὶ νοῦν, ἐπάγεται, τὴν μὲν τῷ μέλει κηλῶν, τὸν δὲ τοῖς νοήμασιν ἐπιστρέφων.", "st": "106"}, {"sp": "N", "t": "καθάπερ γὰρ ὄργανον ἀμούσῳ μὲν παραδοθὲν ἀνάρμοστον, μουσικῷ δὲ κατὰ τὴν ἐν αὐτῷ τέχνην εὐάρμοστον γίνεται, τὸν αὐτὸν τρόπον καὶ ὁ λόγος ὑπὸ μὲν φαύλου νοῦ κινούμενος ἀνάρμοστος, ὑπὸ δὲ σπουδαίου πάνυ ἐμμελὴς εὑρίσκεται.", "st": "107"}, {"sp": "N", "t": "λύρα γε μὴν ἢ εἴ τι τῶν ὁμοίων, εἰ μὴ πληχθείη πρός τινος, ἠρεμεῖ· λόγος τε αὖ μὴ πληχθεὶς ὑφ’ ἡγεμονικοῦ κατὰ τἀναγκαῖον ἡσυχίαν ἄγει. καὶ μὴν ὥσπερ ὄργανα κατὰ τὰς τοῦ μέλους ἀπείρους ὅσας κράσεις μεθαρμόττεται, οὕτως καὶ ὁ λόγος συνῳδός τις ἑρμηνεὺς πραγμάτων γινόμενος ἀμυθήτους λαμβάνει μεταβολάς.", "st": "108"}, {"sp": "N", "t": "τίς γὰρ ἂν ὁμοίως γονεῦσι καὶ τέκνοις διαλεχθείη, τῶν μὲν φύσει δοῦλος, τῶν δὲ γένει δεσπότης ὤν; τίς δ’ ἂν ἀδελφοῖς καὶ ἀνεψιοῖς ἢ συνόλως τοῖς ἐγγὺς γένους καὶ μακρὰν οὖσιν; τίς δ’ ἂν οἰκείοις καὶ ἀλλοτρίοις, ἢ πολίταις καὶ ξένοις, οὐ μικρὰς οὐδὲ * * * τύχης ἢ φύσεως ἢ ἡλικίας ἔχουσι διαφοράς; πρεσβύτῃ γὰρ ἑτέρως ὁμιλητέον καὶ νέῳ, καὶ πάλιν ἐνδόξῳ καὶ ταπεινῷ, καὶ πλουσίῳ καὶ πένητι, καὶ ἄρχοντι καὶ ἰδιώτῃ, καὶ θεράποντι καὶ δεσπότῃ, γυναικί τε αὖ καὶ ἀνδρί, καὶ ἀτέχνῳ καὶ τεχνίτῃ.", "st": "109"}, {"sp": "N", "t": "καὶ τί δεῖ τὰς τῶν προσώπων ἀμυθήτους ἰδέας καταλέγεσθαι, πρὸς ἃς ὁ λόγος τρεπόμενος ἄλλοτε ἀλλοῖα λαμβάνει σχήματα; καὶ γὰρ αἱ τῶν πραγμάτων ἰδιότητες τυποῦσιν αὐτὸν κατὰ τοὺς ἰδίους χαρακτῆρας· μεγάλα γὰρ καὶ μικρὰ ἢ πολλὰ καὶ ὀλίγα ἢ ἰδιωτικὰ καὶ δημόσια ἢ ἱερὰ καὶ βέβηλα ἢ ἀρχαῖα καὶ νέα οὐ τὸν αὐτὸν ἂν ἑρμηνεύσαι τρόπον, ἀλλὰ τὸν ἑκάστοις ἐφαρμόζοντα τῷ πλήθει καὶ ἀξιώματι καὶ μεγέθει, τοτὲ μὲν ὑψηλὸν αἴρων ἑαυτόν, τοτὲ δ’ ἔμπαλιν συνάγων τε καὶ συστέλλων.", "st": "110"}, {"sp": "N", "t": "παρέχουσι δ’ ὥσπερ τὰ πράγματα καὶ τὰ πρόσωπα τῷ λόγῳ μεταβολάς, οὕτως καὶ αἱ τῶν γινομένων αἰτίαι καὶ οἱ τρόποι καθ’ οὓς γίνεται, προσέτι μέντοι καὶ τὰ ὧν οὐκ ἄνευ πάντα, χρόνοι καὶ τόποι. παγκάλως οὖν ὁ μετακλίνων λόγους Ἰουβὰλ πατὴρ εἴρηται ψαλτηρίου καὶ κιθάρας, ἀπὸ μέρους τῆς ὅλης μουσικῆς, ὡς ἐπιδέδεικται.", "st": "111"}, {"sp": "HDR", "t": "Κεφ. XXXIII", "st": "112"}, {"sp": "N", "t": "Τὰ μὲν οὖν τῆς Ἀδᾶς ἔγγονα καὶ αὐτὴ τίς ἐστι δεδήλωται· τὴν δ’ ἑτέραν γυναῖκα τοῦ Λάμεχ Σελλὰν καὶ ὅσα ἀποκύει θεασώμεθα. Σελλὰ τοίνυν ἑρμηνεύεται σκιά, τῶν περὶ σῶμα καὶ ἐκτὸς ἀγαθῶν, ἃ τῷ ὄντι σκιᾶς οὐδὲν διαφέρει, σύμβολον. ἢ κάλλος οὐχὶ σκιά, ὃ πρὸς βραχὺν ἀνθῆσαν χρόνον ἀφαυαίνεται, ἰσχὺς δὲ καὶ εὐτονία σώματος, ἃς ἡ τυχοῦσα νόσος ἐξέλυσεν, αἰσθητήρια δὲ καὶ ἡ περὶ ταῦτα ἀκρίβεια, ἣν ῥεῦμα δυσῶδες ἐνέφραξεν ἢ γῆρας, ἡ ἀναγκαία καὶ κοινὴ πάντων νόσος, ἐπήρωσεν; ἔτι δ’ οὐχὶ πλοῦτοι καὶ δόξαι καὶ ἀρχαὶ καὶ τιμαὶ καὶ ὅσα τῶν ἐκτὸς ἀγαθὰ νενόμισται σκιὰ πάντα;", "st": "112"}, {"sp": "N", "t": "χρὴ δὲ τὴν διάνοιαν ὡς δι’ ἀναβαθμῶν ἐπὶ τὴν τοῦ παντὸς ἐπάγειν ἀρχήν. εἰς Δελφοὺς γεγόνασιν ἄνθρωποι τῶν λεγομένων ἐνδόξων, οἳ τοὺς εὐδαίμονας βίους ἐκεῖσε ἀνατεθείκασι. καθάπερ οὖν ἐξίτηλοι γραφαί, οὐ χρόνου μήκει μόνον [οὐ] διερρύησαν, ἀλλὰ καὶ καιρῶν ὀξείαις μεταβολαῖς ἐκπεπνεύκασιν, εἰσὶ δ’ οὓς οἷα χειμάρρου φορὰ πλημμύροντος ἐξαίφνης ἐπικλύσασα ἠφάνισεν.", "st": "113"}, {"sp": "N", "t": "ἐκ ταύτης τῆς σκιᾶς καὶ τῶν ἀβεβαίων ὀνειράτων ἀποκυεῖται υἱωνός, ὃν ὠνόμασεν Θοβέλ (Gen. 4, 22)· ἑρμηνεύεται δὲ σύμπασα. τῷ γὰρ ὄντι οἱ τὸ παρὰ πολλοῖς ᾀδόμενον ἀγαθὸν σύνθετον πλουθυγείαν κτησάμενοι μικρὰ καὶ μεγάλα καὶ πάνθ’ ἁπλῶς ἀνῆφθαι δοκοῦσιν.", "st": "114"}, {"sp": "N", "t": "εἰ δὲ καὶ παραγένοιτό τις αὐτεξούσιος ἡγεμονία, φυσηθέντες καὶ μετεωρισθέντες ὑπὸ κούφης ἐννοίας, ἐκλαθόμενοι ἑαυτῶν καὶ ὕλης φθαρτῆς ἐξ ἧς γεγόνασι, μείζονος ἢ κατ’ ἀνθρωπίνην σύστασιν οἰηθέντες φύσεως ἐπιλαχεῖν ταῖς τιμαῖς αὑτοὺς ὑπὸ μεγαλαυχίας ἀποσεμνύναντες ἐξεθείωσαν. ἤδη γοῦν τινες ἐπετόλμησαν τὸν ἀληθῆ θεὸν φάναι μὴ εἰδέναι (Exod. 5, 2), τῆς περὶ αὐτοὺς ἀνθρωπότητος ἐκλαθόμενοι, διὰ τὴν τῶν περὶ σῶμα καὶ ἐκτὸς ἀμετρίαν ἀφθόνως * * * οὑς ἕκαστος χαρακτηρίζων.", "st": "115"}, {"sp": "HDR", "t": "Κεφ. XXXIV", "st": "116"}, {"sp": "N", "t": "εἶτά φησιν ὅτι “οὗτος ἦν σφυροκόπος χαλκεὺς χαλκοῦ καὶ σιδήρου” (Gen. 4, 22). τοῦ γὰρ σεσοβημένου περὶ τὰς ἢ σωματικὰς ἡδονὰς [ἢ τὰς ἡδονὰς] ἢ τὰς ἐκτὸς ὕλας ἡ ψυχὴ καθάπερ ἐπ’ ἄκμονος σφυρηλατεῖται κατὰ τὰς τῶν ἐπιθυμιῶν μακρὰς καὶ διωλυγίους ἐκτάσεις ἐλαυνομένη. τοὺς μέν γε φιλοσωμάτους ἴδοις ἂν ἀεὶ καὶ πανταχοῦ λίνα καὶ πάγας πρὸς τῶν ὧν ὀρέγονται θήραν τιθέντας, τοὺς δ’ αὖ φιλαργύρους καὶ φιλοδόξους τὸν περὶ ταῦτα οἶστρον καὶ ἵμερον ἐπὶ τὰ πέρατα γῆς καὶ θαλάττης ἀποστέλλοντας καὶ ὥσπερ δικτύοις ταῖς ἀορίστοις αὑτῶν ὀρέξεσιν ἐπισπωμένους τὰ πανταχόθεν, μέχρις ἂν ὑπὸ βίας ἡ σφοδρὰ τάσις ῥῆξιν λαβοῦσα καὶ τοὺς ἕλκοντας ἀντεπισπωμένη πρηνεῖς καταβάλλῃ.", "st": "116"}, {"sp": "N", "t": "δημιουργοὶ δ’ εἰσὶ πάντες οὗτοι πολέμου, παρὸ σίδηρον καὶ χαλκὸν ἐργάζεσθαι λέγονται, δι’ ὧν οἱ πόλεμοι συνίστανται. τὰς μὲν γὰρ μεγίστας καὶ ἀνδρῶν ἰδίᾳ καὶ πόλεων κοινῇ διαφορὰς εὕροι τις ἂν σκοπῶν καὶ πάλαι γεγενημένας καὶ νῦν ὑπαρχούσας καὶ ἐσομένας αὖθις ἢ εὐμορφίας γυναικὸς εἵνεκα ἢ χρημάτων ἢ δόξης ἢ τιμῆς ἢ ἀρχῆς ἢ κτήσεως ἢ συνόλως ὅσα σώματος καὶ τῶν ἐκτός ἐστι πλεονεκτήματα·", "st": "117"}, {"sp": "N", "t": "παιδείας δὲ καὶ ἀρετῆς χάριν, ἃ τοῦ κρατίστου τῶν ἐν ἡμῖν ἀγαθὰ διανοίας ἐστίν, οὔτε ξενικὸς οὔτ’ ἐμφύλιος πώποτε κατέσχε πόλεμος· εἰρηναῖα γὰρ φύσει ταῦτα, ἐφ’ ὧν εὐνομία καὶ εὐστάθεια καὶ ὅσα περικαλλέστατα εἴδη τοῖς ψυχῆς ὀξυδερκεστάτοις ὄμμασιν, οὐχὶ τοῖς σώματος ἀμυδροῖς, θεωρεῖται· ταῦτα μὲν γὰρ τὰς ἐκτὸς ἐπιφανείας μόνον ὁρᾷ, ὁ δὲ τῆς διανοίας ὀφθαλμὸς εἴσω προελθὼν καὶ βαθύνας τὰ ἐν αὐτοῖς σπλάγχνοις ἐγκεκρυμμένα κατεῖδε.", "st": "118"}, {"sp": "N", "t": "γίνονται δ’ αἱ ταραχαὶ ἢ αἱ στάσεις πᾶσαι τοῖς ἀνθρώποις ἀεὶ σχεδὸν περὶ μὲν οὐδενὸς ἄλλου, περὶ δὲ τῆς πρὸς ἀλήθειαν σκιᾶς. τὸν γὰρ δημιουργὸν τῶν πολεμιστηρίων ὅπλων, χαλκοῦ καὶ σιδήρου, Θοβὲλ υἱὸν Σελλᾶς τῆς σκιᾶς ὠνόμασεν, οὐ λόγων τέχναις, ἀλλὰ νοημάτων ὑπερβάλλοντι κάλλει φιλοσοφῶν. ἔγνω γὰρ ὅτι πᾶς ἢ ναυτικὸς ἢ πεζὸς στρατὸς τοὺς μεγίστους αἱρεῖται κινδύνους ἕνεκα σωματικῶν ἡδονῶν ἢ χάριν περιουσίας τῶν ἐκτός, ὧν οὐδὲν βέβαιον ἢ πάγιον ὑπὸ τοῦ πάντα ἐξελέγχοντος αἰῶνος μαρτυρεῖται· σκιαγραφίαις γὰρ ἐπιπολαίοις ἐξ ἑαυτῶν διαρρεούσαις ἔοικε.", "st": "119"}, {"sp": "HDR", "t": "Κεφ. XXXV", "st": "120"}, {"sp": "N", "t": "τοῦ δὲ Θοβὲλ ἀδελφὴν εἶναί φησι Νοεμάν (Gen. 4, 22), ἧς ἑρμηνεία πιότης· ἀκολουθεῖ γὰρ τοῖς εὐπάθειαν σώματος καὶ ἃς εἶπον ὕλας μεταδιώκουσιν, ὅταν τινὸς ὧν ὀρέγονται λάχωσι, πιαίνεσθαι. τὴν δὲ τοιαύτην πιότητα οὐκ ἰσχύν, ἀλλ’ ἀσθένειαν ἔγωγε τίθεμαι· διδάσκει γὰρ ἀφίστασθαι θεοῦ τιμῆς, ἣ πρώτη καὶ ἀρίστη ψυχῆς ἐστι δύναμις.", "st": "120"}, {"sp": "N", "t": "μάρτυς δ’ ὁ νόμος ἐν ᾠδῇ μείζονι λέγων οὕτως· “ἐλιπάνθη, ἐπαχύνθη, ἐπλατύνθη, καὶ ἐγκατέλιπε θεὸν τὸν ποιήσαντα αὐτόν, καὶ ἐπελάθετο θεοῦ σωτῆρος αὐτοῦ” (Deut. 32, 15). ὄντως γὰρ οὐκέτι μέμνηνται τοῦ αἰωνίου, οἷς πρὸς καιρὸν ὁ βίος ἤνθησε· νομίζουσι γοῦν τὸν καιρὸν θεόν.", "st": "121"}, {"sp": "N", "t": "διὸ καὶ Μωυσῆς μαρτυρεῖ προτρέπων πολεμεῖν ταῖς ἐναντίαις δόξαις· λέγει γάρ· “ἀφέστηκεν ὁ καιρὸς ἀπ’ αὐτῶν, ὁ δὲ κύριος ἐν ἡμῖν” (Num. 14, 9)· ὥσθ’ οἷς μὲν ὁ ψυχῆς βίος τετίμηται, λόγος θεῖος ἐνοικεῖ καὶ ἐμπεριπατεῖ, οἷς δ’ ὁ τῶν ἡδονῶν, ἐφήμερον καὶ κατεψευσμένην ἔχουσιν εὐκαιρίαν. οὗτοι μὲν οὖν ὑπὸ διαρρεούσης πιότητός τε καὶ τέρψεως ἐπὶ πλέον οἰδήσαντες καὶ περιταθέντες ἐξερράγησαν· οἱ δὲ τῇ τρεφούσῃ τὰς φιλαρέτους ψυχὰς σοφίᾳ πιαινόμενοι βέβαιον καὶ ἀκράδαντον ἴσχουσι δύναμιν, ἧς ὑπόδειγμα τὸ ὁλοκαυτούμενον ἀπὸ παντὸς ἱερείου στέαρ.", "st": "122"}, {"sp": "N", "t": "λέγει γὰρ Μωυσῆς· “πᾶν στέαρ τῷ κυρίῳ νόμιμον αἰώνιον” (Lev. 3, 16. 17), ὡς τῆς κατὰ μὲν διάνοιαν πιότητος ἀναφερομένης ἐπὶ θεὸν καὶ οἰκειουμένης αὐτῷ, διόπερ ἀπαθανατίζεται, τῆς δὲ κατὰ τὸ σῶμα καὶ τὰ ἐκτὸς ἀναφερομένης ἐπὶ τὸν ἀντίθεον καιρόν, διὸ καὶ τάχιστα παρήκμασεν.", "st": "123"}, {"sp": "HDR", "t": "Κεφ. XXXVI", "st": "124"}, {"sp": "N", "t": "Περὶ μὲν οὖν τῶν Λάμεχ γυναικῶν τε καὶ ἐκγόνων ἱκανῶς οἶμαι δεδηλῶσθαι· τὴν δ’ ὥσπερ παλιγγενεσίαν Ἄβελ τοῦ δολοφονηθέντος σκεψώμεθα. “ἔγνω” φησίν “Ἀδὰμ τὴν γυναῖκα αὐτοῦ Εὔαν, καὶ συλλαβοῦσα ἔτεκεν υἱόν, καὶ ἐπωνόμασε τὸ ὄνομα αὐτοῦ Σὴθ ⟨λέγουσα⟩· ἐξανέστησε γάρ μοι ὁ θεὸς σπέρμα ἕτερον ἀντὶ Ἄβελ, ὃν ἀπέκτεινε Κάιν” (Gen. 4, 25).", "st": "124"}, {"sp": "N", "t": "Σὴθ ἑρμηνεύεται ποτισμός. ὥσπερ οὖν τὰ κατὰ γῆν σπέρματα καὶ φυτὰ ποτιζόμενα αὔξεται καὶ βλαστάνει καὶ πρὸς καρπῶν γενέσεις εὐτοκεῖ, στερόμενα δὲ ἐπιρροῆς ἀφαυαίνεται, οὕτως ἡ ψυχή, καθάπερ φαίνεται, ὅταν νάματι ποτίμῳ σοφίας ἄρδηται, βλαστάνει τε καὶ ἐπιδίδωσι πρὸς τὸ βέλτιον.", "st": "125"}, {"sp": "N", "t": "ποτισμὸς δὲ ὁ μέν ἐστι ποτίζοντος, ὁ δ’ αὖ ποτιζομένου. ἢ οὐκ ἂν εἴποι τις τῶν αἰσθήσεων ἑκάστην ὥσπερ ἀπὸ πηγῆς τοῦ νοῦ ποτίζεσθαι τὰς δυνάμεις καθάπερ ὀχετοὺς ἀνευρύνοντός τε καὶ τείνοντος; οὐδεὶς γοῦν εὖ φρονῶν εἴποι ἂν ὀφθαλμοὺς ὁρᾶν, ἀλλὰ νοῦν δι’ ὀφθαλμῶν, οὐδ’ ὦτα ἀκούειν, ἀλλὰ δι’ ὤτων ἐκεῖνον, οὐδὲ μυκτῆρας ὀσφραίνεσθαι, ἀλλὰ διὰ μυκτήρων τὸ ἡγεμονικόν.", "st": "126"}, {"sp": "HDR", "t": "Κεφ. XXXVII", "st": "127"}, {"sp": "N", "t": "διὸ καὶ ἐν Γενέσει λέγεται· “πηγὴ δὲ ἀνέβαινεν ἐκ τῆς γῆς καὶ ἐπότιζε πᾶν τὸ πρόσωπον τῆς γῆς” (Gen. 2, 6). ἐπεὶ γὰρ ὅλου τοῦ σώματος μέρος ἐξαίρετον ἔνειμεν ἡ φύσις τὸ πρόσωπον αἰσθήσεσιν, ἡ ἀνιοῦσ’ ἀφ’ ἡγεμονικοῦ πηγὴ σχιζομένη πολλαχῇ καθάπερ τινὰς ὑδρορρόας ἀναστείλασα μέχρι προσώπου, δι’ αὐτῶν τὰς δυνάμεις ἐφ’ ἕκαστον ἄγει τῶν αἰσθητικῶν ὀργάνων. οὕτως μέντοι καὶ ὁ θεοῦ λόγος ποτίζει τὰς ἀρετάς· ἀρχὴ γὰρ καὶ πηγὴ καλῶν πράξεων οὗτος.", "st": "127"}, {"sp": "N", "t": "δηλοῖ δ’ ὁ νομοθέτης φάσκων· “ποταμὸς δ’ ἐκπορεύεται ἐξ Ἐδὲμ ποτίζειν τὸν παράδεισον. ἐκεῖθεν ἀφορίζεται εἰς τέσσαρος ἀρχάς” (Gen. 2, 10). γενικαὶ μὲν γάρ εἰσιν ἀρεταὶ τέσσαρες, φρόνησις, ἀνδρεία, σωφροσύνη, δικαιοσύνη· τούτων δ’ ἡγεμονὶς ἑκάστη καὶ βασιλίς ἐστι, καὶ ὁ κτησάμενος αὐτὰς ἄρχων καὶ βασιλεὺς εὐθέως, κἂν μηδεμιᾶς ὕλης εὐπορῇ.", "st": "128"}, {"sp": "N", "t": "τὸ γὰρ “ἀφορίζεται εἰς τέσσαρας ἀρχὰς” οὐ τούτων διάστασιν, ἀλλ’ ἀρετῶν ἡγεμονίαν ἐμφαίνει καὶ κράτος. αὗται δὲ καθάπερ ἐκ μιᾶς ῥίζης ἐκπεφύκασι τοῦ θείου λόγου, ὃν εἰκάζει ποταμῷ διὰ τὴν ἀένναον καὶ συνεχῆ φορὰν ποτίμων λόγων καὶ δογμάτων, οἷς τὰς φιλοθέους τρέφει καὶ συναύξει ψυχάς.", "st": "129"}, {"sp": "HDR", "t": "Κεφ. XXXVIII", "st": "130"}, {"sp": "N", "t": "ποῖαι δ’ αὗται, κατ’ ὀλίγον ἐπάγων ἐκδιδάσκει, ποιούμενος ἀπὸ τῶν φύσει τὴν ὑφήγησιν τεχνῶν. εἰσάγει γὰρ τὴν Ἄγαρ πληροῦσαν ἀσκὸν ὕδατος καὶ τὸ παιδίον ποτίζουσαν – ἔστι ⟨δ’ ἡ⟩ Ἄγαρ θεραπαινὶς Σάρρας, τῆς τελείας ἀρετῆς [καὶ] μέση παιδεία – φυσικώτατα· ἐπειδὰν οὖν ἄχρι τοῦ βάθους ἐλθοῦσα τῆς ἐπιστήμης, ἣν ὀνομάζει φρέαρ, ἀρύσηται ὥσπερ εἰς ἄγγος τὴν ψυχὴν τά τε δόγματα καὶ θεωρήματα, ἃ μέτεισιν, οἷς τέθραπται, τούτοις τρέφειν τὸ παιδίον ἀξιοῖ.", "st": "130"}, {"sp": "N", "t": "παιδίον δὲ καλεῖ τὴν ἄρτι διδασκαλίας ὀρεγομένην ψυχὴν καὶ πρὸς τῷ μαθεῖν νυνὶ τρόπον τινὰ γεγενημένην, παρὸ καὶ ἀνδρωθεὶς ὁ παῖς γίνεται σοφιστής, ὃν προσαγορεύει τοξότην· ἐφ’ ὃ γὰρ ἂν προθῆται κεφάλαιον ὥσπερ σκοπόν, εὐστόχως ἀποδείξεις ὥσπερ ὀϊστοὺς ἀφίησι.", "st": "131"}, {"sp": "HDR", "t": "Κεφ. XXXIX", "st": "132"}, {"sp": "N", "t": "Ῥεβέκκα δ’ οὐκέτι προκοπαῖς ἀλλὰ τελειότητι ποτίζουσα τὸν μαθητὴν εὑρίσκεται. πῶς δέ, αὐτὸς διδάξει ὁ νόμος. “ἡ γὰρ παρθένος” φησίν “ἦν καλὴ τῇ ὄψει σφόδρα, παρθένος ἦν, ἀνὴρ οὐκ ἔγνω αὐτήν. καταβᾶσα δὲ ἐπὶ τὴν πηγὴν ἔπλησε τὴν ὑδρίαν καὶ ἀνέβη. προσέδραμε δὲ ὁ παῖς εἰς συνάντησιν αὐτῇ καὶ εἶπε· πότισόν με δὴ μικρὸν ὕδωρ ἐκ τῆς ὑδρίας σου. ἡ δὲ εἶπε· πίε, κύριε. καὶ σπεύσασα καθεῖλε τὴν ὑδρίαν ἐπὶ τὸν βραχίονα αὐτῆς καὶ ἐπότισεν αὐτόν, ἕως ἐπαύσατο πίνων· καὶ εἶπε· καὶ ταῖς καμήλοις σου ὑδρεύσομαι, ἕως ἂν πᾶσαι πίωσι. καὶ σπεύσασα ἐξεκένωσε τὴν ὑδρίαν εἰς τὸ ποτιστήριον, καὶ δραμοῦσα ἐπὶ τὸ φρέαρ ὑδρεύσατο ταῖς καμήλοις” (Gen. 24, 16‑20).", "st": "132"}, {"sp": "N", "t": "τίς οὐκ ἂν θαυμάσειε τὴν περὶ πάντα ἀκρίβειαν τοῦ νομοθέτου; παρθένον εἶπε τὴν Ῥεβέκκαν, καὶ πάνυ καλὴν παρθένον, ὅτι ἀμιγὴς καὶ ἄδολος καὶ ἀμίαντος ἡ ἀρετῆς φύσις καὶ μόνη τῶν ἐν γενέσει καλή τε καὶ ἀγαθή· ἀφ’ ἧς καὶ τὸ στωικὸν ἐβλάστησε δόγμα τὸ μόνον εἶναι τὸ καλὸν ἀγαθόν.", "st": "133"}, {"sp": "HDR", "t": "Κεφ. XL", "st": "134"}, {"sp": "N", "t": "τῶν δ’ ἀρετῶν αἱ ⟨μέν⟩ εἰσιν αἰεὶ παρθένοι, αἱ δὲ ἐκ γυναικῶν εἰς παρθένους μετέβαλον, ὥσπερ ἡ Σάρρα· “ἐξέλιπε γὰρ γίνεσθαι τὰ γυναικεῖα” (Gen. 18, 11), ὁπότε ἄρχεται τὸ εὔδαιμον γένος κυοφορεῖν, Ἰσαάκ. ἡ δ’ ἀεὶ παρθένος ὑπὸ ἀνδρός, ᾗ φησι, συνόλως οὐ γινώσκεται. θνητῶν γὰρ πρὸς ἀλήθειαν οὐδενὶ τὴν ἀδιάφθορον φύσιν μιαίνειν ἐφεῖται, ἀλλ’ οὐδ’ ἥτις ἐστὶν εἰλικρινῶς εἰδέναι· ἐὰν μέντοι καὶ γνῶναι δυνηθῇ, μισῶν καὶ προβεβλημένος οὐ παύεται.", "st": "134"}, {"sp": "N", "t": "διὸ καὶ Λείαν φυσικῶς εἰσάγει μισουμένην (Gen. 29, 31)· οὓς γὰρ τὰ φίλτρα τῶν κατὰ Ῥαχήλ, τὴν αἴσθησιν, ἡδονῶν ἐπάγεται, τούτους οὐκ ἀνέχεται ἡ ἐκτὸς τῶν παθῶν Λεία, διόπερ σκορακιζόμενοι μισοῦσιν αὐτήν· τῇ δὲ ἡ πρὸς τὸ γενητὸν ἀλλοτρίωσις πρὸς θεὸν οἰκείωσιν εἰργάσατο, παρ’ οὗ τὰ φρονήσεως παραδεξαμένη σπέρματα ὠδίνει καὶ ἀποτίκτει καλὰς καὶ ἀξίας ἐννοίας τοῦ γεννήσαντος πατρός. ἐὰν οὖν καὶ σὺ μιμησαμένη Λείαν, ὦ ψυχή, ⟨τὰ⟩ θνητὰ ἀποστραφῇς, ἐξ ἀνάγκης ἐπιστρέψει πρὸς τὸν ἄφθαρτον, ὃς ὅλας ἐπομβρήσει σοι τὰς τοῦ καλοῦ πηγάς.", "st": "135"}, {"sp": "N", "t": "<span class=\"hv-secn\">XLI<\/span> ἡ δὲ Ῥεβέκκα κατέβη, φησίν, ἐπὶ τὴν πηγὴν πλῆσαι τὴν ὑδρίαν, καὶ ἀνέβη. πόθεν γὰρ τὴν φρονήσεως διψῶσαν διάνοιαν εἰκός ἐστι πληροῦσθαι πλὴν ἀπὸ σοφίας θεοῦ, τῆς ἀνελλιποῦς πηγῆς, εἰς ἣν κατιοῦσα ἀναβαίνει κατά τι συγγενὲς σπουδαίου μαθητοῦ; τοὺς γὰρ ἀπ’ οἰήσεως χαύνου κατελθόντας ὁ ἀρετῆς ἐκδεξάμενος καὶ ὑπολαβὼν δι’ εὐκλείας εἰς ὕψος αἴρει λόγος. οὗ ἕνεκά μοι δοκεῖ καὶ Μωυσῇ διαλέγεσθαι· “βάδιζε, κατάβηθι, καὶ ἀνάβηθι” (Exod. 19, 24), ὡς παντὸς τοῦ τὴν ἴδιον ταπεινότητα μετροῦντος ἐπικυδεστέρου παρὰ τοῖς ἀληθείας κριταῖς γινομένου.", "st": "136"}, {"sp": "N", "t": "παρατετηρημένως δὲ σφόδρα ἡ μὲν [γὰρ] Ἄγαρ ἀσκὸν πρὸς τὴν ὑδρείαν, Ῥεβέκκα δὲ ὑδρίαν ἐπιφέρεται, ὅτι τῇ μὲν τοῖς παιδεύμασι τοῖς ἐγκυκλίοις ⟨ἐγ⟩χορευούσῃ δεῖ καθάπερ τινῶν σωματικῶν τῆς αἰσθήσεως ἀγγείων, ὀφθαλμῶν, ὤτων, πρὸς τὴν τῶν θεωρημάτων ἀνάληψιν – ἐκ γὰρ τοῦ πολλὰ μὲν ἰδεῖν, πολλῶν δὲ ἐπακοῦσαι περιγίνεται τοῖς φιλομαθέσιν ἡ ἐξ ἐπιστήμης ὠφέλεια – , τῇ δὲ ἀκράτου σοφίας πεπληρωμένῃ δερματίνου μὲν ὄγκου ⟨τὸ⟩ παράπαν οὐδενός – ἔμαθε γὰρ ἡ ἀσωμάτων ἐρῶσα ὅλον ἀποδύεσθαι λογισμῷ τὸν ἀσκόν, τὸ σῶμα – ὑδρίας δὲ αὐτὸ μόνον, ἣ σύμβολόν ἐστιν ἀγγείου τὸ πολύχουν ὕδατος τρόπον ἡγεμονικὸν κεχωρηκότος· ὅπερ εἴτε μήνιγγα εἴτε καρδίαν εἶναι συντέτευχεν, οἱ περὶ ταῦτα δεινοὶ φιλοσοφείτωσαν.", "st": "137"}, {"sp": "N", "t": "ὑδρευσαμένην οὖν ἀπὸ σοφίας, τῆς θείας πηγῆς, τὰς ἐπιστήμας ὁ φιλομαθὴς ἰδὼν ἐπιτρέχει καὶ ὑπαντιάσας ἱκέτης γίνεται, ὅπως τὴν τοῦ μαθεῖν δίψαν ἀκέσηται. ἡ δὲ τὸ πρεσβύτατον τῶν παιδευμάτων διδαχθεῖσα, τὸ ἀβάσκανον καὶ φιλόδωρον, εὐθὺς ὀρέγει τὸ σοφίας νᾶμα καὶ ἐμπιεῖν ἀθρόου παρακαλεῖ μετὰ τοῦ καὶ κύριον ὀνομάζειν τὸν οἰκέτην. τοῦτο δ’ ἐστὶ τὸ δογματικώτατον, ὅτι ὁ σοφὸς μόνος ἐλεύθερός τε καὶ ἄρχων, κἂν μυρίους τοῦ σώματος ἔχῃ δεσπότας.", "st": "138"}, {"sp": "N", "t": "<span class=\"hv-secn\">XLII<\/span> ὀρθότατα μέντοι φαμένου “πότισόν με μικρὸν ὕδωρ”, οὐκ ἀποκρίνεται τὸν ἀκόλουθον τρόπον· ποτιῶ, ἀλλά φησι· “πίε”· τοῦτο μὲν γὰρ ἐπιδεικνυμένης τὸν θεῖον ἦν πλοῦτον, ὃς ἅπασι τοῖς ἀξίοις καὶ δυναμένοις χρῆσθαι προκέχυται, ἐκεῖνο δὲ ἐπαγγελλομένης διδάξειν· οὐδὲν δὲ τῶν ἐξ ἐπαγγέλματος οἰκεῖον ἀρετῇ.", "st": "139"}, {"sp": "N", "t": "τεχνικώτατα μέντοι χαρακτηρίζει τὴν τῆς διδασκούσης καὶ ὠφελούσης ὑφήγησιν· “σπεύσασα” γάρ φησι “καθεῖλε τὴν ὑδρίαν ἐπὶ τὸν βραχίονα αὐτῆς”, διὰ μὲν τοῦ σπουδάσαι τῆς πρὸς τὸ εὐεργετεῖν ἐμφαινομένης ὀξύτητος, ἣ ἀπὸ γνώμης συνίσταται, ἧς ὑπερόριος ἐκτετόξευται φθόνος, διὰ δὲ τοῦ καθελεῖν ἐπὶ τὸν βραχίονα αὐτῆς ⟨τῆς⟩ πρὸς τὸν μανθάνοντα τοῦ διδάσκοντος ἐπικλινοῦς καὶ προσεχοῦς οἰκειώσεως.", "st": "140"}, {"sp": "N", "t": "εὐήθεις γὰρ ὅσοι τῶν διδασκάλων μὴ πρὸς τὴν τῶν γνωρίμων δύναμιν, ἀλλὰ πρὸς τὴν ἑαυτῶν ὑπερβάλλουσαν ἕξιν ἐπιχειροῦσι ποιεῖσθαι τὰς ὑφηγήσεις, οὐκ εἰδότες ὡς διδασκαλίας ἐπίδειξις μακρῷ διενήνοχεν. ὁ μὲν γὰρ ἐπιδεικνύμενος τῇ τῆς παρούσης ἕξεως εὐφορίᾳ καταχρώμενος ἀνεμποδίστως τὰ ἐν μακρῷ χρόνῳ πονηθέντα οἴκοι καθάπερ γραφέων ἔργα ἢ πλαστῶν εἰς τοὐμφανὲς προφέρει τὸν παρὰ τῶν πολλῶν θηρώμενος ἔπαινον, ὁ δ’ αὖ διδάσκειν ἐπιχειρῶν οἷά τις ἰατρὸς ἀγαθὸς οὐ πρὸς τὸ τῆς τέχνης μέγεθος ἀλλὰ πρὸς τὴν τοῦ θεραπευομένου δύναμιν ἀφορῶν οὐχ ὅσα ἐκ τῆς ἐπιστήμης πεπόρικε – ἀμύθητα γὰρ ταῦτά γε – , ἀλλ’ ὅσων τῷ κάμνοντι δεῖ στοχαζόμενος τοῦ μετρίου προφέρων ἐπιδίδωσιν.", "st": "141"}, {"sp": "N", "t": "<span class=\"hv-secn\">XLIII<\/span> διὸ καὶ Μωυσῆς ἐν ἑτέροις φησί· “δάνειον δανειεῖς τῷ χρῄζοντι ὅσον δεῖται, καθ’ ὃ δεῖται” (Deut. 15, 8), διὰ μὲν τοῦ δευτέρου διδάσκων ὅτι οὐ πάντα πᾶσι χαριστέον, ἀλλὰ τὰ οἰκεῖα τῇ τῶν δεομένων χρείᾳ· τὸ γὰρ ἄγκυραν ἢ πλάτην ἢ πηδάλιον γεωπόνῳ ἢ ἄροτρα καὶ σκαπάνην κυβερνήτῃ ἢ λύραν μὲν ἰατρῷ, μουσικῷ δὲ τὰ κατὰ τὴν χειρουργίαν δωρεῖσθαι ὄργανα καταγέλαστον, εἰ μὴ καὶ διψῶσι μὲν πολυτελῆ σιτία, πεινῶσι δὲ πολὺν ἄκρατον ἐπιφέρειν δεῖ πρὸς ἐπίδειξιν εὐπορίας τε ἅμα καὶ μισανθρωπίας, χλεύην τὰς ἑτέρων τύχας τιθεμένους. τὸ δὲ ποσὸν ἐν ταῖς χάρισιν αὐτῷ παρείληπται διὰ συμμετρίαν, πρᾶγμα ὠφελιμώτατον· μὴ γὰρ ὅσα δύνασαι χαρίζου, φησὶν ὁ ὀρθὸς λόγος, ἀλλ’ ὅσα ἱκανὸς ὁ δεόμενός ἐστι δέξασθαι.", "st": "142"}, {"sp": "N", "t": "ἢ οὐχ ὁρᾷς ὅτι καὶ ὁ θεὸς οὐκ ἀναλογοῦντας τῷ μεγέθει τῆς αὑτοῦ τελειότητος χρησμοὺς ἀναφθέγγεται, πρὸς δὲ τὴν τῶν ὠφεληθησομένων ἀεὶ δύναμιν; ἐπεὶ καὶ τίς ἂν ἐχώρησε θεοῦ λόγων ἰσχὺν τῶν ἁπάσης κρειττόνων ἀκοῆς; ὃ ἀψευδέστατα δοκοῦσιν οἱ Μωυσῇ λέγοντες· “λάλησον σὺ ἡμῖν, καὶ μὴ λαλείτω πρὸς ἡμᾶς ὁ θεός, μὴ ἀποθάνωμεν” (Exod. 20, 19)· ἔγνωσαν γὰρ ὅτι οὐδὲν ἔχουσι παρ’ ἑαυτοῖς ἀξιόχρεων ὄργανον θεοῦ νομοθετοῦντος ἐκκλησίαν.", "st": "143"}, {"sp": "N", "t": "οὐδὲ γὰρ εἰ τὸν πλοῦτον ἐπιδείκνυσθαι βουληθείη τὸν ἑαυτοῦ, χωρήσαι ἂν ἠπειρωθείσης καὶ θαλάττης ἡ σύμπασα γῆ· εἰ μὴ νομίζομεν ὑετῶν καὶ τῶν ἄλλων ἐν κόσμῳ φορὰν κατὰ τεταγμένας καιρῶν περιόδους, ἀλλὰ μὴ συνεχῶς γίνεσθαι διὰ σπάνιν καὶ ἔνδειαν αὐτῶν, ἀλλ’ οὐχ ἕνεκα προμηθείας τῶν χρῃζόντων, οὓς ἡ συνεχὴς τῶν ὁμοίων δωρεῶν ἀπόλαυσις βλάψειν μᾶλλον ἔμελλεν ἢ ὠφελήσειν.", "st": "144"}, {"sp": "N", "t": "διὸ τὰς πρώτας αἰεὶ χάριτας, πρὶν κορεσθέντας ἐξυβρίσαι τοὺς λαχόντας, ἐπισχὼν καὶ ταμιευσάμενος εἰσαῦθις ἑτέρας ἀντ’ ἐκείνων καὶ τρίτας ἀντὶ τῶν δευτέρων καὶ αἰεὶ νέας ἀντὶ παλαιοτέρων, τοτὲ μὲν διαφερούσας, τοτὲ δ’ αὖ καὶ τὰς αὐτὰς ἐπιδίδωσι. τὸ γὰρ γενητὸν οὐδέποτε μὲν ἀμοιρεῖ τῶν τοῦ θεοῦ χαρίτων – ἐπεὶ πάντως ἂν διέφθαρτο – , φέρειν δὲ τὴν πολλὴν καὶ ἄφθονον αὐτῶν ῥύμην ἀδυνατεῖ. διὸ βουλόμενος ὄνησιν ἡμᾶς ἔχειν ὧν ἐπιδίδωσι πρὸς τὴν τῶν λαμβανόντων ἰσχὺν τὰ διδόμενα σταθμᾶται.", "st": "145"}, {"sp": "N", "t": "<span class=\"hv-secn\">XLIV<\/span> ἐπαινετέον οὖν καὶ Ῥεβέκκαν, ἣ τοῖς τοῦ πατρὸς ἑπομένη διατάγμασιν ἀφ’ ὑψηλοτέρου χωρίου καθελοῦσα τὸ σοφίας ἀγγεῖον ἐπὶ τὸν βραχίονα, τὴν ὑδρίαν [δὲ], ὀρέγει τῷ μαθητῇ ἃς ἱκανὸς ἐκεῖνός ἐστι δέξασθαι διδασκαλίας.", "st": "146"}, {"sp": "N", "t": "μετὰ δὲ τῶν ἄλλων καὶ τὸ ἄφθονον αὐτῆς καταπέπληγμαι. μικρὸν γὰρ αἰτηθεῖσα πόμα πολὺ δίδωσιν, ἕως ὅλην τὴν ψυχὴν τοῦ μανθάνοντος ποτίμων θεωρημάτων ἐπλήρωσεν. λέγει γάρ· “ἐπότισεν αὐτὸν ἕως ἐπαύσατο πίνων”, πρὸς φιλανθρωπίαν δίδαγμα θαυμασιώτατον· ἐὰν γάρ τις πλειόνων μὲν τυγχάνῃ χρεῖος ὤν, ὀλίγα δὲ ὑπ’ αἰδοῦς προσιὼν αἰτῇ, μὴ ταῦθ’ ἅ φησι μόνα παρέχωμεν, ἀλλὰ καὶ τὰ ἡσυχαζόμενα ἐκεῖνα, ὧν πρὸς ἀλήθειαν ἐνδεής ἐστιν.", "st": "147"}, {"sp": "N", "t": "ἀλλ’ οὐκ ἀπόχρη μόνον πρὸς τελείαν ἀπόλαυσιν τῷ γνωρίμῳ καταλαμβάνειν ὅσα ἂν ὁ διδάσκων ὑφηγῆται, εἰ μὴ προσγένοιτο καὶ μνήμη διόπερ ἐπιδεικνυμένη τὸ φιλόδωρον, ὅτε αὐτὸν πληροῖ ποτίσασα, ὑπισχνεῖται καὶ ταῖς καμήλοις ὑδρεύσεσθαι, ἃς συμβολικῶς μνήμας εἶναί φαμεν· μηρυκᾶται γὰρ τὸ ζῷον τὴν τροφὴν ἐπιλεαῖνον, καὶ ὅταν ὀκλάσαν δέξηται βαρύτατον φόρτον, μετὰ πολλῆς ἄγαν εὐτονίας ἐγείρεται κούφως.", "st": "148"}, {"sp": "N", "t": "οὕτως δὲ καὶ ἡ ψυχὴ τοῦ φιλομαθοῦς, ὅταν ἐπιφορηθῇ τὸ τῶν θεωρημάτων ἄχθος, ταπεινοτέρα μὲν οὐ γίνεται, διαναστᾶσα δὲ γέγηθεν· ἐκ δὲ τῆς ἐπαναπολήσεως καὶ ὥσπερ ἐπιλεάνσεως τῆς πρῶτον καταβληθείσης τροφῆς περιγίνεται μνήμη τῶν θεωρημάτων.", "st": "149"}, {"sp": "N", "t": "ἰδοῦσα δὲ εὐπαράδεκτον ἀρετῆς ⟨τὴν⟩ τοῦ παιδὸς φύσιν ὅλην ἐξεκένωσε τὴν ὑδρίαν εἰς τὸ ποτιστήριον, τουτέστι τὴν τοῦ διδάσκοντος ἅπασαν ἐπιστήμην εἰς τὴν ψυχὴν τοῦ μανθάνοντος. σοφισταὶ μὲν γὰρ ὑπὸ μισθαρνίας ἅμα καὶ φθόνου τὰς τῶν γνωρίμων κολούοντες φύσεις πολλὰ τῶν ἃ χρὴ λέγειν ἡσυχάζουσι ταμιευόμενοι τὸν ἀργυρισμὸν εἰσαῦθις ἑαυτοῖς·", "st": "150"}, {"sp": "N", "t": "ἄφθονον δὲ καὶ δωρητικὸν ἀρετὴ πρᾶγμα, ὡς, τὸ λεγόμενον, χειρὶ καὶ ποδὶ καὶ πάσῃ δυνάμει μὴ ὀκνεῖν ὠφελεῖν. ὅσα οὖν ἠπίστατο, καθάπερ εἰς δεξαμενὴν τὴν τοῦ γνωρίμου προχέασα διάνοιαν ἔρχεται πάλιν ἐπὶ τὸ φρέαρ ἀντλῆσαι, ἐπὶ τὴν ἀένναον τοῦ θεοῦ σοφίαν, ἵνα καὶ τὰ ⟨παλαιὰ⟩ παγίως ὀχυρώσηται διὰ μνήμης καὶ ἄλλων καινοτέρων ἐπιστήμαις ποτισθῇ· ἀπερίγραφος γὰρ ὁ σοφίας θεοῦ πλοῦτος καὶ νέα ἐπὶ παλαιοῖς ἐκφέρων βλαστήματα, ὡς ἀνηβῶν τε καὶ ἐπακμάζων μηδέποτε λήγειν.", "st": "151"}, {"sp": "N", "t": "διὸ καὶ πάνυ εὐήθεις ὅσοι πρὸς τὸ πέρας ἡστινοσοῦν ἐπιστήμης ἀφικέσθαι διενοήθησαν· τὸ γὰρ ἐγγὺς εἶναι δόξαν μακρὰν ἄγαν τοῦ τέλους ἀφέστηκεν, ἐπεὶ τέλειος τῶν γεγονότων οὐδεὶς πρὸς οὐδὲν μάθημα, ἀλλὰ τοσοῦτον ἐνδεῖ, ὅσον κομιδῇ νήπιος παῖς ἄρτι τοῦ μανθάνειν ἀρχόμενος πρὸς πολιὸν ἤδη διὰ τὴν ἡλικίαν ἅμα καὶ τὴν τέχνην ὑφηγητήν.", "st": "152"}, {"sp": "N", "t": "<span class=\"hv-secn\">XLV<\/span> ἐρευνητέον δὲ τὴν αἰτίαν, δι’ ἣν τὸν μὲν παῖδα ἀπὸ τῆς πηγῆς, τὰς δὲ καμήλους ἀπὸ τοῦ φρέατος ποτίζει. μήποτ’ οὖν τὸ μὲν νᾶμα ταὐτόν, * * * ὁ τὰς ἐπιστήμας ἄρδων [ὁ] ἱερὸς λόγος, τὸ δὲ φρέαρ συγγενὲς μνήμης· ἃ γὰρ βύθια ἀπέφηνεν ἤδη, ταῦθ’ ὥσπερ ἐκ φρέατος δι’ ὑπομνήσεως ἄγεται.", "st": "153"}, {"sp": "N", "t": "τοὺς μὲν οὖν τοιούτους τῆς περὶ τὴν φύσιν εὐμοιρίας ἀποδεκτέον· εἰσὶ δέ τινες τῶν ἀσκητῶν, οἷς τὴν ἐπ’ ἀρετὴν ἄγουσαν ὁδὸν τραχεῖαν καὶ δυσάντη καὶ χαλεπὴν νομισθεῖσαν τὸ πρῶτον λεωφόρον αὖθις ὁ τὰ πάντα εὐεργέτης ἀπέδειξε θεὸς εἰς γλυκύτητα τὸ πικρὸν τοῦ πόνου μεταβαλών.", "st": "154"}, {"sp": "N", "t": "ὃν δὲ τρόπον μετέβαλε, σημανοῦμεν· ὅτε ἡμᾶς ἐκ τῆς Αἰγύπτου, τῶν κατὰ τὸ σῶμα παθῶν, ἐξήγαγε, τὴν ἔρημον ἡδονῆς ἀτραπὸν ὁδεύοντες ἐν Μέρροις ἐστρατοπεδευόμεθα, χωρίῳ πότιμον μὲν οὐκ ἔχοντι νᾶμα, πικρὸν δὲ σύμπαν (Exod. 15, 23)· ἔτι γὰρ αἱ δι’ ὀφθαλμῶν καὶ ὤτων γαστρός τε αὖ καὶ τῶν μετὰ γαστέρα τέρψεις ἔναυλοί τε ἦσαν καὶ σφόδρα ἐκήλουν ὑπηχοῦσαι.", "st": "155"}, {"sp": "N", "t": "ὁπότ’ οὖν διαποζεύγνυσθαι κατὰ τὸ παντελὲς ἐθέλοιμεν, ἀνθεῖλκον ἐπαγόμεναι καὶ περιπλεκόμεναι καὶ λιπαρῶς καταγοητεύουσαι, ὥστε πρὸς τὰς συνεχεῖς τιθασείας αὐτῶν ἐνδόντες πόνῳ μὲν ἠλλοτριούμεθα ὡς πικρῷ πάνυ καὶ δυσκόλῳ, παλινδρομεῖν δὲ εἰς Αἴγυπτον ἐβουλευόμεθα, τὸν ἀσελγοῦς καὶ ἀκολάστου βίου ὑπόδρομον, εἰ μὴ θᾶττον ὁ σωτὴρ οἶκτον λαβὼν καθάπερ ἥδυσμα ξύλον γλυκαῖνον (cf. Exod. 15, 25) εἰς τὴν ψυχὴν ἐνέβαλε φιλοπονίαν ἀντὶ μισοπονίας ἐργασάμενος·", "st": "156"}, {"sp": "N", "t": "ᾔδει γάρ, ἅτε δημιουργὸς ὤν, ὅτι τῶν ὄντων οὐδενός, εἰ μὴ προσγένοιτο σφοδρὸς ἔρως, ἔνεστι περιγενέσθαι. ὅσα οὖν ἐπιτηδεύουσιν ἄνθρωποι, δίχα μὲν οἰκειώσεως τῆς πρὸς αὐτὰ τὸ ἁρμόττον τέλος οὐ λαμβάνει, προσγενομένης δὲ φιλίας καὶ τῆς πρὸς τὸ ποθούμενον συντήξεως ἄκρως κατορθοῦται.", "st": "157"}, {"sp": "N", "t": "<span class=\"hv-secn\">XLVI<\/span> αὕτη τροφὴ ψυχῆς ἀσκητικῆς, ἥδιστον ἀντὶ πικροῦ τὸ πονεῖν ὑπολαβεῖν, ἧς οὐχ ἅπασι κοινωνῆσαι θέμις, ἀλλ’ οἷς ὁ χρυσοῦς μόσχος, τὸ Αἰγυπτίων ἀφίδρυμα, τὸ σῶμα, πυρωθὲν καὶ λεανθὲν σπείρεται καθ’ ὕδατος. λέγεται γὰρ ἐν ἱεραῖς βίβλοις, ὅτι “λαβὼν Μωυσῆς τὸν μόσχον κατέκαυσε πυρὶ καὶ κατήλεσε λεπτὸν καὶ ἔσπειρεν ἐπὶ τὸ ὕδωρ, καὶ ἐπότισε τοὺς υἱοὺς Ἰσραήλ” (Exod. 32, 20).", "st": "158"}, {"sp": "N", "t": "ὁ γὰρ φιλάρετος ὑπὸ τῆς αὐγοειδοῦς τοῦ καλοῦ φαντασίας πυρωθεὶς καταφλέγει τὰς σωματικὰς ἡδονάς, εἶτα κατακόπτει καὶ ἐπιλεαίνει τῷ ἀπὸ διαιρέσεως λόγῳ χρώμενος, καὶ διδάσκει τὸν τρόπον τοῦτον ὅτι τῶν σωματικῶν ἀγαθῶν ἐστιν ὑγίεια ἢ κάλλος ἢ ἡ τῶν αἰσθήσεων ἀκρίβεια ἢ τὸ ὁλόκληρον μετὰ ἰσχύος καὶ ῥώμης κρατερᾶς, ἅ γε πάντα καὶ τῶν ἐπαράτων καὶ ἐξαγίστων ἐστὶ κοινά, ὧν, εἴπερ ἦν ἀγαθά, φαῦλος οὐδενὸς οὐδεὶς ἂν μετεῖχε.", "st": "159"}, {"sp": "N", "t": "ἀλλ’ οὗτοι μέν, εἰ καὶ παντάπασι μοχθηροί, ἀλλ’ ἄνθρωποί γε ὄντες καὶ τῆς αὐτῆς φύσεως τοῖς ἀστείοις κεκοινωνηκότες μετέχουσιν αὐτῶν. νυνὶ δὲ καὶ τῶν θηρίων τὰ ἀτιθασώτατα μᾶλλον τοῖς ἀγαθοῖς τούτοις, εἰ δὴ ἀγαθὰ πρὸς ἀλήθειάν ἐστιν, ἢ οἱ λογικοὶ κέχρηνται.", "st": "160"}, {"sp": "N", "t": "τίς γὰρ ἂν ἀθλητὴς πρὸς ταύρου δύναμιν ἢ ἐλέφαντος ἀλκὴν ἐξισωθείη; τίς δ’ ἂν δρομεὺς πρὸς σκύλακος ἢ λαγωδαρίου ποδώκειαν; ὁ μὲν γὰρ ἀνθρώπων ὀξυδερκέστατος πρὸς ἱεράκων ἢ ἀετῶν ὄψιν ἀμβλυωπέστατος. ἀκοαῖς γε μὴν ἢ ὀσμαῖς πολλῷ τῷ περιόντι τὰ ἄλογα κεκράτηκεν, ὡς καὶ ὄνος μέν, τὸ δοκοῦν ἐν ζῴοις εἶναι νωθέστατον, κωφὴν ἂν ἀποδείξαι τὴν ἡμετέραν ἀκοὴν ἐλθὼν εἰς ἐπίκρισιν, κύων δὲ περιττὸν ἐν ἀνθρώπῳ μυκτῆρας μέρος δι’ ὑπερβολὴν τοῦ περὶ τὰς ὀσμὰς τάχους· ἐξικνοῦνται γὰρ ἐπὶ μήκιστον, ὡς ὀφθαλμῶν ἁμιλλᾶσθαι φορᾷ.", "st": "161"}, {"sp": "N", "t": "<span class=\"hv-secn\">XLVII<\/span> καὶ τί δεῖ περὶ ἑκάστου διεξιόντα μακρηγορεῖν; ἤδη γὰρ τοῦτο παρὰ τοῖς δοκιμωτάτοις τῶν πάλαι λογίων ὡμολόγηται, οἳ τῶν μὲν ἀλόγων μητέρα τὴν φύσιν, ἀνθρώπων δὲ μητρυιὰν ἔφασαν εἶναι, τὴν κατὰ σῶμα τῶν μὲν ἀσθένειαν, τῶν δὲ ὑπερβάλλουσαν ἐν ἅπασιν ἰσχὺν κατανοήσαντες. εἰκότως οὖν κατήλεσε τὸν μόσχον ὁ τεχνίτης, τουτέστιν εἰς μέρη διελὼν τὰ οἷς σῶμα πλεονεκτεῖ πάντα τοῦ πρὸς ἀλήθειαν ἐπέδειξεν ἀγαθοῦ μακρὰν διεστῶτα καὶ μηδὲν τῶν ἐφ’ ὕδατος σπειρομένων διαφέροντα.", "st": "162"}, {"sp": "N", "t": "διὸ καὶ τὸν καταλεσθέντα μόσχον ἐπὶ τὸ ὕδωρ λόγος κατέχει σπαρῆναι, τοῦ μηδὲν γνήσιον ἀγαθοῦ φυτὸν ἐν ὕλῃ φθαρτῇ ποτε δύνασθαι βλαστάνειν σύμβολον. ὡς γὰρ εἰς ποταμοῦ ῥεῦμα ἢ θαλάττης καταβληθὲν σπέρμα τὰς ἰδίους οὐκ ἂν ἐπιδείξαιτο δυνάμεις – ἀμήχανον γάρ, εἰ ⟨μὴ⟩ ῥίζαις ὥσπερ ἀγκύραις ἐχυροῦ τινος γῆς μέρους ἅπαξ λαβόμενον ἱδρυθείη, ἢ ἔρνος ἀναβλαστῆσαι, καὶ εἰ μὴ περιμηκέστατον, ἀλλά τοι χαμαίζηλον, ἢ καρποὺς καθ’ ὥρας τὰς ἐτησίους ἐνεγκεῖν· φθάνει γὰρ τοὺς σπερματικοὺς ἅπαντας τόνους ἡ τοῦ ὕδατος πολλὴ καὶ βίαιος ἀποκλύσασα φορά – , τὸν αὐτὸν τρόπον ὅσα τοῦ τῆς ψυχῆς ἀγγείου λέγεταί τε καὶ ᾄδεται πλεονεκτήματα πρὶν ὑποστῆναι φθείρεται τῆς σωματικῆς οὐσίας αἰεὶ ῥεούσης.", "st": "163"}, {"sp": "N", "t": "πῶς γὰρ νόσοι καὶ γῆρας καὶ παντελεῖς ἐπεγίνοντο φθοραί, εἰ μὴ συνεχὴς ἦν λόγῳ θεωρητῶν ῥευμάτων ἀπάντλησις; τούτοις οὖν ποτίζειν ἀπαξιοῖ ⟨ὁ⟩ ἱεροφάντης τὴν διάνοιαν ἡμῶν τῷ καταφλέξαι τὰς ἡδονάς, τῷ τὸ σύστημα τῶν σωματικῶν ἀγαθῶν εἰς λεπτὸν καὶ ἀνωφελῆ χοῦν καταλέσαντας ἀναλῦσαι, τῷ ὑπολαβεῖν ὅτι ἐξ οὐδενὸς αὐτῶν ἐβλάστησέ ποτε καὶ ἤνθησε τὸ πρὸς ἀλήθειαν καλόν, ὥσπερ οὐδ’ ἐκ σπερμάτων ἃ σπείρεται καθ’ ὕδατος.", "st": "164"}, {"sp": "N", "t": "<span class=\"hv-secn\">XLVIII<\/span> ταῦροι δὲ καὶ κριοὶ καὶ τράγοι, οὓς Αἴγυπτος διὰ τιμῆς ἔχει, καὶ ὅσα ἄλλα φθαρτῆς ὕλης ἀφιδρύματα, ἀκοῇ μόνον νομίζονται θεοί, πρὸς ἀλήθειαν οὐκ ὄντες, ψευδώνυμοι πάντες. ἁπαλαῖς γὰρ ἔτι ταῖς τῶν νέων ψυχαῖς οἱ τραγῳδίαν τὸν βίον τύφων ἐρώντων νομίζοντες κεκιβδηλευμένους χαρακτῆρας ἐναπομάττονται, διακόνοις ἀκοαῖς χρώμενοι, ὧν μυθικὸν λῆρον καταχέαντες καὶ μέχρι διανοίας αὐτῶν ἐντήξαντες θεοπλαστεῖν τοὺς τὰ φρονήματα ἄνδρας μὲν μηδέποτε γινομένους ἀεὶ δὲ θηλυδρίας ὄντας ἠνάγκασαν.", "st": "165"}, {"sp": "N", "t": "ὁ γοῦν μόσχος οὐκ ἐξ ἅπαντος τοῦ γυναικείου κόσμου κατασκευάζεται, ἀλλ’ ἐκ τῶν ἐνωτίων αὐτὸ μόνον (Exod. 32, 2), διδάσκοντος ἡμᾶς τοῦ νομοθέτου ὅτι χειρόκμητος οὐδείς ἐστιν ὄψει καὶ πρὸς ἀλήθειαν θεός, ἀλλ’ ἀκοῇ καὶ τῷ νομίζεσθαι, καὶ ἀκοῇ μέντοι γυναικός, οὐκ ἀνδρός· ἐκνενευρισμένης γὰρ ἔργον καὶ ἐκτεθηλυμμένης τῷ ὄντι ψυχῆς τοὺς τοιούτους ὕθλους παραδέχεσθαι.", "st": "166"}, {"sp": "N", "t": "τὸ δὲ πρὸς ἀλήθειαν ὂν οὐ δι’ ὤτων μόνον, ἀλλὰ τοῖς διανοίας ὄμμασιν ἐκ τῶν κατὰ τὸν κόσμον δυνάμεων καὶ ἐκ τῆς συνεχοῦς καὶ ἀπαύστου τῶν ἀμυθήτων ἔργων φορᾶς κατανοεῖσθαί τε καὶ γνωρίζεσθαι συμβέβηκε. διόπερ ἐν ᾠδῇ μείζονι λέγεται ἐκ προσώπου τοῦ θεοῦ· “ἴδετε ἴδετε, ὅτι ἐγώ εἰμι” (Deut. 33, 39), τοῦ ὄντως ὄντος ἐναργείᾳ μᾶλλον [ἀντι]καταλαμβανομένου ἢ λόγων ἀποδείξει συνισταμένου.", "st": "167"}, {"sp": "N", "t": "τὸ δ’ ὁρατὸν εἶναι τὸ ὂν οὐ κυριολογεῖται, κατάχρησις δ’ ἐστὶν ἐφ’ ἑκάστην αὐτοῦ τῶν δυνάμεων ἀναφερομένου. καὶ γὰρ νῦν οὔ φησιν· ἴδετε ἐμέ – ἀμήχανον γὰρ τὸν κατὰ τὸ εἶναι θεὸν ὑπὸ γενέσεως τὸ παράπαν κατανοηθῆναι – , ἀλλ’ ὅτι ἐγώ εἰμι ἴδετε, τουτέστι τὴν ἐμὴν ὕπαρξιν θεάσασθε. ἀνθρώπου γὰρ ἐξαρκεῖ λογισμῷ μέχρι τοῦ καταμαθεῖν ὅτι ἔστι τε καὶ ὑπάρχει τὸ τῶν ὅλων αἴτιον προελθεῖν· περαιτέρω δὲ σπουδάζειν τρέπεσθαι, ὡς περὶ οὐσίας ἢ ποιότητος ζητεῖν, ὠγύγιός τις ἠλιθιότης.", "st": "168"}, {"sp": "N", "t": "οὐδὲ γὰρ Μωυσῇ τῷ πανσόφῳ κατένευσεν ὁ θεὸς τοῦτό γε, καίτοι γε μυρίας ποιησαμένῳ δεήσεις, ἀλλὰ χρησμὸς ἐξέπεσεν αὐτῷ, ὅτι “τὰ μὲν ὀπίσω θεάσῃ, τὸ δὲ πρόσωπον οὐκ ὄψει” (Exod. 33, 23)· τοῦτο δ’ ἦν· πάνθ’ ὅσα μετὰ τὸν θεὸν τῷ σπουδαίῳ καταληπτά, αὐτὸς δὲ μόνος ἀκατάληπτος· ἀκατάληπτός γε ἐκ τῆς ἀντικρὺς καὶ κατ’ εὐθυωρίαν προσβολῆς – διὰ γὰρ ταύτης οἷος ἦν ἐμηνύετ’ ἄν – , ἐκ δὲ τῶν ἑπομένων καὶ ἀκολούθων δυνάμεων ⟨καταληπτός⟩· αὗται γὰρ οὐ τὴν οὐσίαν, τὴν δ’ ὕπαρξιν ἐκ τῶν ἀποτελουμένων αὐτῷ παριστᾶσι.", "st": "169"}, {"sp": "N", "t": "<span class=\"hv-secn\">XLIX<\/span> Γεννήσας τοίνυν ὁ νοῦς ἀρχὴν σπουδαίας διαθέσεως καὶ ἀρετῆς τινα πρῶτον τρόπον τὸν Σήθ, τὸν ποτισμόν, ἐπινεανιεύεται καλὴν καὶ ὁσίαν νεανιείαν. φησὶ γάρ· “ἐξανέστησέ μοι ὁ θεὸς σπέρμα ἕτερον ἀντὶ Ἄβελ, ὃν ἀπέκτεινε Κάιν” (Gen. 4, 25). ἐξητασμένως γὰρ καὶ περιττῶς εἴρηται τὸ μηδὲν τῶν θείων σπερμάτων χαμαὶ πίπτειν, ἅπαντα δὲ εἰς τὸ ἄνω χωρεῖν ἀπὸ τῶν περιγείων ἐξανιστάμενα.", "st": "170"}, {"sp": "N", "t": "τὰ μὲν γὰρ ὑπὸ τῶν θνητῶν καταβαλλόμενα σπέρματα πρὸς ζῴων ἢ φυτῶν γένεσιν οὐ πάντα τελεσιουργεῖται, ἀγαπητὸν δ’ εἰ μὴ τὰ φθειρόμενα πλείω τῶν διαμενόντων ἐστί· σπείρει δ’ ὁ θεὸς ἐν ψυχαῖς ἀτελὲς οὐδέν, ἀλλ’ οὕτως καίρια καὶ τέλεια, ὡς εὐθὺς ἐπιφέρεσθαι τὴν τῶν ἰδίων καρπῶν πληθὺν ἕκαστον.", "st": "171"}, {"sp": "HDR", "t": "Κεφ. L", "st": "172"}, {"sp": "N", "t": "τὸν δὲ Σὴθ σπέρμα ἕτερον εἰπὼν ἀναβλαστῆσαι, ὁποτέρου ἕτερον οὐ δεδήλωκε. ἆρά γε τοῦ δολοφονηθέντος Ἄβελ ἢ τοῦ κτείναντος Κάιν; ἀλλὰ μήποτε ἑκατέρου διαφέρει τὸ γέννημα, τοῦ μὲν Κάιν ὡς ἐχθρόν – δίψα γὰρ ἀρετῆς αὐτομολούσῃ κακίᾳ πολεμιώτατον – , τοῦ δὲ Ἄβελ ὡς φίλον καὶ συγγενές· ἕτερον γάρ, οὐ μὴν ἀλλότριον, τὸ ἄρτι ἀρχόμενον τοῦ τελείου καὶ τὸ πρὸς γένεσιν τοῦ πρὸς τὸ ἀγένητον.", "st": "172"}, {"sp": "N", "t": "διὰ τοῦθ’ ὁ μὲν Ἄβελ τὸ θνητὸν ἀπολιπὼν πρὸς τὴν ἀμείνω φύσιν μεταναστὰς οἴχεται, ὁ δὲ Σὴθ ἅτε σπέρμα ὢν ἀνθρωπίνης ἀρετῆς οὐδέποτε τὸ ἀνθρώπων ἀπολείψει γένος, ἀλλὰ πρώτην μὲν παραύξησιν ἄχρι δεκάδος ἀριθμοῦ τελείου λήψεται, καθ’ ἣν ὁ δίκαιος Νῶε συνίσταται, δευτέραν δὲ καὶ ἀμείνω τὴν ἀπὸ τοῦ παιδὸς αὐτοῦ Σὴμ εἰς ἑτέραν δεκάδα τελευτῶσαν, ἧς Ἀβραὰμ ὁ πιστὸς ἐπώνυμος, τρίτην δὲ καὶ τελεωτέραν δεκάδος ἑβδομάδα ἀπὸ τούτου μέχρι Μωυσῆ τοῦ πάντα σοφοῦ παρήκουσαν· ἕβδομος γὰρ ἀπὸ Ἀβραὰμ οὗτός ἐστιν, οὐκέτι κατὰ τὸν ἔξω τῶν ἁγίων κύκλον οἷα μύστης εἰλούμενος, ἀλλ’ ὥσπερ ἱεροφάντης ἐν τοῖς ἀδύτοις ποιούμενος τὰς διατριβάς.", "st": "173"}, {"sp": "HDR", "t": "Κεφ. LI", "st": "174"}, {"sp": "N", "t": "σκόπει δὲ τάς τε πρὸς βελτίωσιν ἐπιδόσεις τῆς ἀπλήστου καὶ ἀκορέστου τῶν καλῶν ψυχῆς καὶ τὸν ἀπερίγραφον τοῦ θεοῦ πλοῦτον, ὃς ἄλλοις ἀρχὰς τὰ ἑτέρων δεδώρηται τέλη. τὸ μὲν γὰρ πέρας τῆς κατὰ Σὴθ ἐπιστήμης ἀρχὴ τοῦ δικαίου γέγονε Νῶε, τὴν δὲ τούτου τελείωσιν Ἀβραὰμ ἄρχεται παιδεύεσθαι, ἡ δὲ ἀκροτάτη τοῦδε σοφία Μωυσέως ἐστὶν ἄσκησις ἡ πρώτη.", "st": "174"}, {"sp": "N", "t": "τοῦ δὲ ἀνωσμένου καὶ κλιθέντος ὑπὸ ψυχῆς ἀσθενείας Λὼτ αἱ δύο θυγατέρες, βουλὴ καὶ συγκατάθεσις, ἐκ τοῦ νοῦ τοῦ πατρὸς αὑτῶν ἐθέλουσι παιδοποιεῖσθαι (Gen. 19, 32), μαχόμεναι τῷ λέγοντι· “ἐξανέστησέ μοι ὁ θεός”. ὃ γὰρ ἐκείνῳ τὸ ὄν, τοῦθ’ αὑταῖς φασι τὸν νοῦν περιποιεῖσθαι δύνασθαι, μεθυούσης καὶ παραφόρου ψυχῆς δόγμα εἰσηγούμεναι· νήφοντος μὲν γὰρ ἔργον λογισμοῦ καὶ ⟨σώφρονος⟩ τὸν θεὸν ὁμολογεῖν ποιητὴν καὶ πατέρα τοῦ παντός, πίπτοντος δ’ ὑπὸ μέθης καὶ παροινίας ἑαυτὸν ἑκάστου τῶν ἀνθρωπείων πραγμάτων εἶναι δημιουργόν.", "st": "175"}, {"sp": "N", "t": "πρότερον οὖν αἱ κακαὶ γνῶμαι εἰς ὁμιλίαν οὐκ ἀφίξονται τῷ πατρί, πρὶν ἐπιφορῆσαι τὸν ἀφροσύνης πολὺν ἄκρατον καὶ εἴ τι συνετὸν ἦν ἐν αὐτῷ κατακλύσαι. γέγραπται γὰρ ὅτι “ἐπότισαν τὸν πατέρα οἶνον” (Gen. 19, 33)· ὥσθ’ ὁπότε μὴ ποτίζουσιν, ὑπὸ νήφοντος οὐδέποτε δέξονται σπορὰν ἔννομον, ὅταν δ’ ὑποβεβρεγμένος κραιπαλᾷ, κυοφορήσουσι καὶ ἐπιμέμπτοις μὲν ὠδῖσιν, ἐπαράτοις δὲ ταῖς γοναῖς χρήσονται.", "st": "176"}, {"sp": "HDR", "t": "Κεφ. LII", "st": "177"}, {"sp": "N", "t": "διὸ καὶ Μωυσῆς τὴν ἀσεβῆ καὶ ἄναγνον αὐτῶν σπορὰν συλλόγου θείου παντὸς ἀπεσχοίνισε· λέγει γάρ· “Ἀμμανῖται καὶ Μωαβῖται οὐκ εἰσελεύσονται εἰς ἐκκλησίαν κυρίου” (Deut. 23, 2). οὗτοι δ’ εἰσὶν ἔγγονοι τῶν Λὼτ θυγατέρων, ὑπολαβόντες ἐξ αἰσθήσεως καὶ νοῦ, ἄρρενός τε καὶ θήλεος, ὥσπερ ὑπὸ πατρὸς καὶ μητρὸς πάντα γεννᾶσθαι, τοῦτο πρὸς ἀλήθειαν γενέσεως αἴτιον ὑπειληφότες.", "st": "177"}, {"sp": "N", "t": "ἡμεῖς μέντοι καὶ ἐὰν δεξώμεθά ποτε τὴν τροπὴν ταύτην, [καὶ] ὥσπερ ἐκ κλύδωνος ἀνανηξάμενοι λαβώμεθα μετανοίας, ἐχυροῦ καὶ σωτηρίου πράγματος, καὶ μὴ πρότερον μεθώμεθα ἢ κατὰ τὸ παντελὲς τὸ κυμαῖνον πέλαγος, τὴν φορὰν τῆς τροπῆς, διεκδῦναι.", "st": "178"}, {"sp": "N", "t": "καθὰ καὶ Ῥαχὴλ πρότερον αἰτησαμένη τὸν νοῦν ὡς αἴτιον τοῦ ποιεῖν ἔκγονα καὶ ἀκούσασα· “μὴ ἀντὶ θεοῦ ἐγώ εἰμι”; (Gen. 30, 2) προσέσχε τε τῷ λεχθέντι καὶ μαθοῦσα παλινῳδίαν ἱερωτάτην ἐποίησε· γέγραπται γὰρ Ῥαχὴλ παλινῳδία, θεοφιλὴς εὐχή· “προσθέτω μοι ὁ θεὸς υἱὸν ἕτερον” (Gen. 30, 24), ἣν οὐδενὶ τῶν ἀφρόνων ἔξεστι ποιήσασθαι τὴν ἴδιον ἡδονὴν αὐτὸ μόνον θηρωμένων, τὰ δ’ ἄλλα πλατὺν γέλωτα καὶ χλεύην νομιζόντων.", "st": "179"}, {"sp": "HDR", "t": "Κεφ. LIII", "st": "180"}, {"sp": "N", "t": "χορηγὸς δ’ ἐστὶ τούτου τοῦ δόγματος ὁ τοῦ δερματίνου Ἢρ συγγενὴς Αὐνάν. “γνοὺς” γάρ φησιν “οὗτος ὅτι οὐκ αὐτῷ ἔσται τὸ σπέρμα, ὅταν εἰσῆλθε πρὸς τὴν γυναῖκα τοῦ ἀδελφοῦ, ἐξέχει τοῦτο ἐπὶ τὴν γῆν” (Gen. 38, 9) φιλαυτίας καὶ φιληδονίας ὑπερβεβηκὼς τοὺς ὅρους.", "st": "180"}, {"sp": "N", "t": "οὐκοῦν εἴποιμ’ ἂν αὐτῷ· εἰ τὸ ἴδιον πορίζεις λυσιτελές, πάνθ’ ὅσα ἄριστα καταλύσεις, ἐὰν μηδὲν ἐξ αὐτῶν ὠφεληθῇς, τιμὰς γονέων, ἐπιμέλειαν γυναικός, παίδων ἀγωγάς, χρήσεις ἀμέμπτους οἰκετῶν, ἐπιτροπὴν οἰκίας, πόλεως προστασίαν, βεβαίωσιν νόμων, φυλακὴν ἐθῶν, τὴν πρὸς πρεσβυτέρους αἰδῶ, τὴν πρὸς τοὺς τετελευτηκότας εὐφημίαν, τὴν πρὸς τοὺς ζῶντας κοινωνίαν, τὴν πρὸς τὸ θεῖον ἐν λόγοις καὶ ἔργοις εὐσέβειαν; ἀνατρέπεις γὰρ καὶ ἐκχεῖς πάντα ταῦτα, σπείρων σεαυτῷ καὶ τιθηνούμενος τὴν γάστριν καὶ ἀκόλαστον καὶ ἀρχὴν κακῶν ἁπάντων ἡδονήν.", "st": "181"}, {"sp": "HDR", "t": "Κεφ. LIV", "st": "182"}, {"sp": "N", "t": "ἀφ’ ἧς ἐξαναστὰς ὁ ἱερεὺς καὶ θεραπευτὴς τοῦ μόνου καλοῦ Φινεές, ὁ τῶν σωματικῶν στομίων καὶ τρημάτων δίοπος, ὡς μηδὲν αὐτῶν διαμαρτάνον ἐξυβρίζειν – ἑρμηνεύεται γὰρ στόματος φιμός – , λαβὼν τὸν σειρομάστην, τουτέστι μαστεύσας καὶ ἀναζητήσας τὴν τῶν ὄντων φύσιν καὶ μηδὲν σεμνότερον ἀρετῆς ἀνευρὼν κατεκέντει καὶ ἀνῄρει τῷ λόγῳ τὴν μισάρετον καὶ φιλήδονον γένεσιν καὶ τοὺς τόπους, ἐξ ὧν ἐβλάστησαν αἱ παράσημοι καὶ παράκοποι χλιδαί τε καὶ θρύψεις.", "st": "182"}, {"sp": "N", "t": "ὁ γὰρ νόμος ⟨φησὶν⟩ ὅτι διὰ τῆς μήτρας ἐξεκέντησε τὴν γυναῖκα (Num. 25, 7. 8). οὕτως οὖν καταπαύσας μὲν τὴν ἐν αὑτῷ στάσιν καὶ τὴν ἴδιον ἀποστραφεὶς ἡδονήν, ζηλώσας τὸν θεοῦ τοῦ πρώτου καὶ μόνου ζῆλον, ἄθλων τοῖς μεγίστοις δυσὶ τετίμηται καὶ κατέστεπται, εἰρήνῃ καὶ ἱερωσύνῃ· τῇ μέν, * * * ὅτι ἀδελφόν ἐστιν εἰρήνῃ καὶ ὄνομα καὶ ἔργον.", "st": "183"}, {"sp": "N", "t": "τὴν γὰρ ἱερωμένην διάνοιαν λειτουργὸν καὶ θεραπευτρίδα οὖσαν αὐτοῦ πάνθ’ οἷς ὁ δεσπότης χαίρει πράττειν ἀνάγκη· χαίρει δὲ εὐνομίας καὶ εὐσταθείας βεβαιώσει, πολέμων δὲ καὶ στάσεων ἀνατροπῇ, οὐχὶ τῶνδε μόνων οὓς αἱ πόλεις ποιοῦνται πρὸς ἀλλήλας, ἀλλὰ καὶ τῶν κατὰ ψυχήν· μείζονες δ’ εἰσὶν οὗτοι καὶ χαλεπώτεροι, ἅτε καὶ τὸ θειότερον τῶν ἐν ἡμῖν λογισμὸν αἰκιζόμενοι, τῶν ὅπλων ἄχρι τῆς σωμάτων καὶ χρημάτων ζημίας προερχομένων, ψυχὴν δὲ ὑγιαίνουσαν μηδέποτε βλάψαι δυναμένων.", "st": "184"}, {"sp": "N", "t": "διόπερ ὀρθῶς ἂν αἱ πόλεις ἐποίησαν, πρὶν ὅπλα καὶ μηχανήματα ἀντεπιφέρειν ἀλλήλαις ἐπ’ ἀνδραποδισμῷ καὶ ἀναστάσει παντελεῖ, τῶν πολιτῶν ἕκαστον ἀναπείσασαι τὴν ἐν αὐτῷ μεγάλην καὶ πολλὴν καὶ συνεχῆ στάσιν καταλῦσαι· αὕτη μὲν γὰρ πολέμων, εἰ δεῖ τἀληθὲς εἰπεῖν, ἁπάντων ἀρχέτυπόν ἐστιν, ἧς ἀναιρεθείσης οὐδ’ οἱ κατὰ μίμησιν ἔτι συνιστάμενοι γενήσονται, βαθείας δὲ εἰρήνης χρῆσιν καὶ ἀπόλαυσιν σχήσει τὸ ἀνθρώπων γένος ὑπὸ νόμου φύσεως διδασκόμενον, ἀρετῆς, θεὸν τιμᾶν καὶ τῆς λειτουργίας αὐτοῦ περιέχεσθαι· πηγὴ γὰρ εὐδαιμονίας καὶ βίου μακραίωνος ἥδε.", "st": "185"}],[]);})();
